.equipment-card {
  max-height: 88vh;
  overflow-y: auto;
}

.equipment-unit-tabs {
  margin-top: 16px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.equipment-unit-tabs button,
.equipment-list button {
  min-height: 42px;
  border: none;
  border-radius: 12px;
  background: linear-gradient(to bottom, #311010, #140505);
  color: #f5d28c;
  font-weight: 900;
  border: 1px solid rgba(255,215,150,0.15);
}

.equipment-unit-tabs .active-tab {
  box-shadow: 0 0 0 2px #ffe27a inset;
}

.equipment-list {
  margin-top: 14px;
  display: grid;
  gap: 8px;
}

.equipment-list button {
  padding: 10px;
  text-align: left;
}

.equipment-list button:disabled {
  opacity: 0.35;
}


.training-list,
.support-list {
  margin-top: 16px;
  display: grid;
  gap: 10px;
}

.training-list button,
.support-list button {
  min-height: 58px;
  border: none;
  border-radius: 14px;
  background: linear-gradient(to bottom, #311010, #140505);
  color: #f5d28c;
  font-weight: 900;
  border: 1px solid rgba(255,215,150,0.16);
  padding: 12px;
  text-align: left;
}

.support-list button strong {
  display: block;
  font-size: 16px;
  color: #f5d28c;
}

.support-list button span {
  display: block;
  margin-top: 5px;
  color: #77ffbb;
  font-size: 13px;
}

.support-list button small {
  display: block;
  margin-top: 7px;
  color: #d8c8c8;
  font-size: 12px;
  line-height: 1.5;
}


.status-badges {
  position: absolute;
  right: 1px;
  bottom: 1px;
  z-index: 5;
  display: flex;
  gap: 1px;
  pointer-events: none;
}

.status-badges span {
  min-width: 16px;
  height: 16px;
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.72);
  border: 1px solid rgba(255, 215, 150, 0.35);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
}



.phase2-unit {
  box-shadow:
    0 0 0 3px #ff3333,
    0 0 18px rgba(255, 0, 0, 0.85),
    0 0 34px rgba(120, 0, 0, 0.75);
  animation: phasePulse 1.1s infinite alternate;
}

@keyframes phasePulse {
  from {
    transform: scale(1);
    filter: brightness(1);
  }

  to {
    transform: scale(1.08);
    filter: brightness(1.35);
  }
}

/* v1.99.72: hard stop movement clones and expose blocked terrain on concept maps. */
.battle-screen.battle-final-concept.battle-board-only .battle-map.classic-pixel-map .unit.sprite-unit.moving-hidden,
.battle-screen.battle-final-concept.battle-board-only .battle-map.classic-pixel-map .unit.sprite-unit.moving-hidden *,
.battle-screen.battle-final-concept.battle-board-only .battle-map.classic-pixel-map .unit.sprite-unit.moving-source-shadow,
.battle-screen.battle-final-concept.battle-board-only .battle-map.classic-pixel-map .unit.sprite-unit.moving-source-shadow * {
  opacity: 0 !important;
  visibility: hidden !important;
  filter: none !important;
  animation: none !important;
  pointer-events: none !important;
}

.battle-screen.battle-final-concept.battle-board-only .battle-map.classic-pixel-map .unit.sprite-unit.moving-hidden::before,
.battle-screen.battle-final-concept.battle-board-only .battle-map.classic-pixel-map .unit.sprite-unit.moving-hidden::after,
.battle-screen.battle-final-concept.battle-board-only .battle-map.classic-pixel-map .unit.sprite-unit.moving-source-shadow::before,
.battle-screen.battle-final-concept.battle-board-only .battle-map.classic-pixel-map .unit.sprite-unit.moving-source-shadow::after {
  content: none !important;
  display: none !important;
  opacity: 0 !important;
  visibility: hidden !important;
}

.battle-screen.battle-final-concept.battle-board-only .battle-map.classic-pixel-map .moving-overlay-hidden {
  display: none !important;
  opacity: 0 !important;
  visibility: hidden !important;
}

.battle-screen.battle-final-concept.battle-board-only .battle-map.classic-pixel-map > .tile.terrain-block,
.battle-screen.battle-final-concept.battle-board-only .battle-map.classic-pixel-map > .tile.block,
.battle-screen.battle-final-concept.battle-board-only .battle-map.classic-pixel-map > .tile.terrain-wall,
.battle-screen.battle-final-concept.battle-board-only .battle-map.classic-pixel-map > .tile.terrain-void {
  background:
    radial-gradient(circle at 50% 42%, rgba(0, 0, 0, 0.22), rgba(0, 0, 0, 0.06) 62%, transparent 76%) !important;
  border: 1px solid rgba(18, 10, 6, 0.22) !important;
  box-shadow:
    inset 0 0 0 1px rgba(255, 226, 150, 0.08),
    inset 0 0 14px rgba(0, 0, 0, 0.28) !important;
}

.battle-screen.battle-final-concept.battle-board-only .battle-map.classic-pixel-map > .tile.terrain-block::after,
.battle-screen.battle-final-concept.battle-board-only .battle-map.classic-pixel-map > .tile.block::after,
.battle-screen.battle-final-concept.battle-board-only .battle-map.classic-pixel-map > .tile.terrain-wall::after,
.battle-screen.battle-final-concept.battle-board-only .battle-map.classic-pixel-map > .tile.terrain-void::after {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  inset: 18% !important;
  opacity: 0.5 !important;
  border-radius: 4px !important;
  background:
    linear-gradient(135deg, transparent 42%, rgba(255, 218, 128, 0.44) 46%, rgba(255, 218, 128, 0.44) 54%, transparent 58%),
    linear-gradient(45deg, transparent 42%, rgba(0, 0, 0, 0.38) 46%, rgba(0, 0, 0, 0.38) 54%, transparent 58%) !important;
  border: 1px solid rgba(255, 218, 128, 0.18) !important;
  box-shadow: 0 0 8px rgba(0, 0, 0, 0.26) !important;
  pointer-events: none !important;
}

.phase-banner {
  position: fixed;
  z-index: 80;
  top: 22%;
  left: 50%;
  transform: translateX(-50%);
  width: min(360px, 86vw);
  padding: 18px 20px;
  border-radius: 22px;
  background:
    radial-gradient(circle at top, rgba(255, 0, 0, 0.45), transparent 65%),
    linear-gradient(to bottom, rgba(80, 0, 0, 0.96), rgba(10, 0, 0, 0.96));
  border: 1px solid rgba(255, 210, 140, 0.35);
  color: #f5d28c;
  text-align: center;
  font-size: 30px;
  font-weight: 900;
  letter-spacing: 2px;
  text-shadow:
    0 0 12px rgba(255,0,0,0.8),
    0 0 24px rgba(255,180,80,0.45);
  box-shadow:
    0 0 30px rgba(255,0,0,0.35),
    inset 0 0 25px rgba(255,0,0,0.15);
  pointer-events: none;
  animation: bannerDrop 1.4s ease both;
}

@keyframes bannerDrop {
  0% {
    opacity: 0;
    transform: translate(-50%, -16px) scale(0.9);
  }

  18% {
    opacity: 1;
    transform: translate(-50%, 0) scale(1.04);
  }

  78% {
    opacity: 1;
    transform: translate(-50%, 0) scale(1);
  }

  100% {
    opacity: 0;
    transform: translate(-50%, -10px) scale(0.96);
  }
}


.danger-tile {
  position: absolute;
  inset: 6%;
  border-radius: 12px;
  background:
    radial-gradient(circle, rgba(255, 0, 0, 0.5), rgba(80, 0, 0, 0.18));
  border: 2px solid rgba(255, 40, 40, 0.95);
  box-shadow:
    0 0 14px rgba(255, 0, 0, 0.85),
    inset 0 0 14px rgba(255, 0, 0, 0.35);
  animation: dangerPulse 0.85s infinite alternate;
  z-index: 1;
}

@keyframes dangerPulse {
  from {
    opacity: 0.55;
    transform: scale(0.94);
  }

  to {
    opacity: 1;
    transform: scale(1.03);
  }
}

.turn-busy-banner {
  position: fixed;
  z-index: 70;
  left: 50%;
  bottom: 24px;
  transform: translateX(-50%);
  padding: 10px 16px;
  border-radius: 999px;
  background: rgba(0,0,0,0.72);
  border: 1px solid rgba(255,215,150,0.25);
  color: #f5d28c;
  font-size: 14px;
  font-weight: 900;
  letter-spacing: 1px;
  pointer-events: none;
}

.action-panel button:disabled,
.camp-btn:disabled,
.back-btn:disabled {
  opacity: 0.45;
  filter: grayscale(0.7);
}


.tile.fort {
  background:
    linear-gradient(135deg, rgba(190, 180, 160, 0.25), transparent 36%),
    linear-gradient(to bottom, #6c6760, #3d3834);
  box-shadow: inset 0 0 12px rgba(0, 0, 0, 0.22);
}

.tile.gate {
  background:
    linear-gradient(90deg, rgba(0,0,0,0.25) 0 8%, transparent 8% 92%, rgba(0,0,0,0.25) 92%),
    linear-gradient(to bottom, #7a5b3a, #3b2717);
  box-shadow:
    inset 0 0 18px rgba(0,0,0,0.35),
    0 0 10px rgba(255, 190, 90, 0.08);
}

.tile.road {
  background:
    linear-gradient(to bottom, #8b7552, #5d4b33);
}


.tile.ice {
  background:
    radial-gradient(circle at center, rgba(210, 245, 255, 0.55), transparent 54%),
    linear-gradient(to bottom, #86b7c8, #315c70);
  box-shadow:
    inset 0 0 14px rgba(220, 255, 255, 0.32),
    0 0 10px rgba(120, 220, 255, 0.16);
}


