/* v0.26 전투 이펙트 */

.screen-shake-normal {
  animation: screenShakeNormal 0.32s ease both;
}

.screen-shake-strong {
  animation: screenShakeStrong 0.52s ease both;
}

@keyframes screenShakeNormal {
  0% { transform: translate(0, 0); }
  20% { transform: translate(-2px, 1px); }
  40% { transform: translate(2px, -1px); }
  60% { transform: translate(-1px, 2px); }
  80% { transform: translate(1px, -2px); }
  100% { transform: translate(0, 0); }
}

@keyframes screenShakeStrong {
  0% { transform: translate(0, 0); }
  12% { transform: translate(-5px, 3px); }
  24% { transform: translate(4px, -3px); }
  36% { transform: translate(-4px, -2px); }
  48% { transform: translate(5px, 2px); }
  60% { transform: translate(-3px, 4px); }
  72% { transform: translate(3px, -4px); }
  100% { transform: translate(0, 0); }
}

.combat-effect {
  position: absolute;
  inset: -18%;
  z-index: 8;
  pointer-events: none;
}

.effect-slash::before,
.effect-counter::before,
.effect-crit::before {
  content: "";
  position: absolute;
  left: 8%;
  top: 46%;
  width: 84%;
  height: 8px;
  border-radius: 999px;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.95), rgba(245,210,140,0.9), transparent);
  box-shadow:
    0 0 12px rgba(255,255,255,0.9),
    0 0 20px rgba(245,210,140,0.45);
  transform: rotate(-32deg) scaleX(0);
  animation: slashFx 0.46s ease-out forwards;
}

.effect-counter::before {
  transform: rotate(28deg) scaleX(0);
  background: linear-gradient(90deg, transparent, rgba(180,220,255,0.95), rgba(255,255,255,0.95), transparent);
}

.effect-crit::before {
  height: 10px;
  background: linear-gradient(90deg, transparent, #fff, #ff3333, #ffd86b, transparent);
  box-shadow:
    0 0 16px rgba(255,40,40,0.95),
    0 0 30px rgba(255,220,80,0.55);
  animation: critSlashFx 0.58s ease-out forwards;
}

@keyframes slashFx {
  0% { opacity: 0; transform: rotate(-32deg) scaleX(0); }
  25% { opacity: 1; }
  100% { opacity: 0; transform: rotate(-32deg) scaleX(1.28); }
}

@keyframes critSlashFx {
  0% { opacity: 0; transform: rotate(-32deg) scaleX(0) scaleY(1); }
  20% { opacity: 1; }
  60% { opacity: 1; transform: rotate(-32deg) scaleX(1.35) scaleY(1.35); }
  100% { opacity: 0; transform: rotate(-32deg) scaleX(1.65) scaleY(1.7); }
}

.effect-fire,
.effect-magic,
.effect-ice,
.effect-shadow,
.effect-hazard,
.effect-miss {
  border-radius: 50%;
  animation: radialFx 0.72s ease-out forwards;
}

.effect-fire {
  background:
    radial-gradient(circle, rgba(255,230,80,0.95), rgba(255,85,20,0.75) 35%, rgba(140,0,0,0.16) 64%, transparent 70%);
  box-shadow:
    0 0 18px rgba(255,90,0,0.75),
    inset 0 0 20px rgba(255,255,120,0.35);
}

.effect-magic {
  background:
    radial-gradient(circle, rgba(190,120,255,0.85), rgba(90,20,150,0.36) 55%, transparent 72%);
  box-shadow: 0 0 20px rgba(180,90,255,0.75);
}

.effect-ice {
  background:
    radial-gradient(circle, rgba(230,255,255,0.9), rgba(80,190,255,0.55) 48%, transparent 72%);
  box-shadow: 0 0 20px rgba(120,230,255,0.82);
}

.effect-shadow,
.effect-hazard {
  background:
    radial-gradient(circle, rgba(255,40,40,0.92), rgba(80,0,0,0.72) 42%, rgba(0,0,0,0.2) 64%, transparent 78%);
  box-shadow:
    0 0 24px rgba(255,0,0,0.9),
    inset 0 0 22px rgba(0,0,0,0.48);
}

.effect-hazard {
  inset: -28%;
  animation: hazardBoom 0.92s ease-out forwards;
}

.effect-miss::before {
  content: "MISS";
  position: absolute;
  left: 50%;
  top: 35%;
  transform: translateX(-50%);
  color: rgba(255,255,255,0.9);
  font-weight: 900;
  font-size: 13px;
  text-shadow: 0 0 8px rgba(0,0,0,0.75);
  animation: missFloat 0.72s ease-out forwards;
}

@keyframes radialFx {
  0% { opacity: 0; transform: scale(0.22); }
  28% { opacity: 1; }
  100% { opacity: 0; transform: scale(1.35); }
}

@keyframes hazardBoom {
  0% { opacity: 0; transform: scale(0.22) rotate(0deg); }
  25% { opacity: 1; }
  72% { opacity: 0.9; transform: scale(1.18) rotate(18deg); }
  100% { opacity: 0; transform: scale(1.65) rotate(36deg); }
}

@keyframes missFloat {
  0% { opacity: 0; transform: translate(-50%, 8px) scale(0.85); }
  25% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -18px) scale(1.05); }
}

.damage-popup {
  position: absolute;
  left: 50%;
  top: -8px;
  z-index: 11;
  min-width: 30px;
  padding: 3px 6px;
  border-radius: 999px;
  transform: translateX(-50%);
  color: white;
  font-weight: 900;
  font-size: 15px;
  text-align: center;
  pointer-events: none;
  text-shadow:
    0 0 5px rgba(0,0,0,0.9),
    0 0 10px rgba(0,0,0,0.65);
  animation: damagePopup 0.9s ease-out forwards;
}

.popup-damage {
  color: #ff8787;
}

.popup-crit {
  color: #ffd86b;
  font-size: 17px;
  filter: drop-shadow(0 0 8px rgba(255,70,70,0.75));
}

.popup-miss {
  color: #dfe8ff;
}

.popup-hazard {
  color: #ff5a5a;
}

@keyframes damagePopup {
  0% { opacity: 0; transform: translate(-50%, 10px) scale(0.8); }
  18% { opacity: 1; transform: translate(-50%, -2px) scale(1.18); }
  72% { opacity: 1; transform: translate(-50%, -20px) scale(1); }
  100% { opacity: 0; transform: translate(-50%, -34px) scale(0.96); }
}

.phase2-unit img {
  filter:
    drop-shadow(0 2px 3px rgba(0,0,0,0.8))
    drop-shadow(0 0 12px rgba(255,0,0,0.95))
    drop-shadow(0 0 20px rgba(255,60,60,0.55)) !important;
}

.danger-tile::after {
  content: "";
  position: absolute;
  inset: 18%;
  border-radius: 50%;
  border: 2px solid rgba(255, 210, 120, 0.55);
  animation: dangerRune 1.1s linear infinite;
}

@keyframes dangerRune {
  from { transform: rotate(0deg) scale(0.96); opacity: 0.55; }
  to { transform: rotate(360deg) scale(1.04); opacity: 0.95; }
}



