  border: 2px solid rgba(110, 220, 255, 0.8);
  box-shadow:
    inset 0 0 16px rgba(120, 220, 255, 0.18),
    0 0 8px rgba(80, 180, 255, 0.35);
  animation: moveTilePulse 1.2s ease-in-out infinite alternate;
}

.attack-tile {
  inset: 7%;
  z-index: 5;
  background:
    radial-gradient(circle at center, rgba(255, 80, 80, 0.24), rgba(170, 20, 20, 0.10) 58%, rgba(170, 20, 20, 0.04));
  border: 2px solid rgba(255, 110, 110, 0.85);
  box-shadow:
    inset 0 0 16px rgba(255, 70, 70, 0.18),
    0 0 10px rgba(255, 70, 70, 0.35);
  animation: attackTilePulse 0.95s ease-in-out infinite alternate;
}

@keyframes moveTilePulse {
  from {
    opacity: 0.74;
    transform: scale(0.98);
  }

  to {
    opacity: 1;
    transform: scale(1.02);
  }
}

@keyframes attackTilePulse {
  from {
    opacity: 0.72;
    transform: scale(0.98);
  }

  to {
    opacity: 1;
    transform: scale(1.04);
  }
}

/* 핵심: 아군/적/보스 모두 같은 타일 기준으로 보이게 축소 */
.sprite-unit {
  inset: 12%;
  overflow: visible;
}

.sprite-unit img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  transform: scale(1.06) translateY(3%) !important;
  filter:
    drop-shadow(0 2px 2px rgba(0,0,0,0.78))
    drop-shadow(0 0 4px rgba(0,0,0,0.42));
}

.sprite-unit.ally-unit img {
  filter:
    drop-shadow(0 2px 2px rgba(0,0,0,0.78))
    drop-shadow(0 0 5px rgba(80,150,255,0.38));
}

.sprite-unit.enemy-unit img {
  filter:
    drop-shadow(0 2px 2px rgba(0,0,0,0.78))
    drop-shadow(0 0 5px rgba(255,80,80,0.34));
}

.sprite-unit.boss-unit img {
  transform: scale(1.12) translateY(1%) !important;
  filter:
    drop-shadow(0 2px 3px rgba(0,0,0,0.84))
    drop-shadow(0 0 7px rgba(255,0,0,0.48))
    drop-shadow(0 0 5px rgba(255,210,100,0.34));
}

/* 보스도 과하게 크지 않게. 대신 오라로 위압감 유지 */
.phase2-unit img {
  transform: scale(1.14) translateY(1%) !important;
  filter:
    drop-shadow(0 2px 3px rgba(0,0,0,0.84))
    drop-shadow(0 0 12px rgba(255,0,0,0.88))
    drop-shadow(0 0 18px rgba(255,60,60,0.46)) !important;
}

