    0 0 0 2px #ffe27a,
    0 0 15px rgba(255,226,122,0.72);
}

.ally-unit::after,
.enemy-unit::after,
.boss-unit::after {
  content: "";
  position: absolute;
  left: 22%;
  right: 22%;
  bottom: -2px;
  height: 4px;
  border-radius: 999px;
  background: rgba(0,0,0,0.55);
  z-index: -1;
}

