/* v0.46 유닛 이동 모션 */

.moving-unit-layer {
  position: absolute;
  inset: 8px;
  z-index: 60;
  pointer-events: none;
}

.map-moving-unit {
  position: absolute;
  left: calc(var(--from-x) * 100% / var(--cols));
  top: calc(var(--from-y) * 100% / var(--rows));
  width: calc(100% / var(--cols));
  height: calc(100% / var(--rows));
  display: flex;
  align-items: center;
  justify-content: center;
  animation: unitMapMove var(--move-duration, 460ms) cubic-bezier(0.2, 0.86, 0.18, 1) forwards;
  will-change: transform;
}

.map-moving-unit img {
  width: 92%;
  height: 92%;
  object-fit: contain;
  image-rendering: auto;
  animation: unitMoveBob 0.16s ease-in-out infinite alternate;
  filter:
    drop-shadow(0 4px 4px rgba(0,0,0,0.88))
    drop-shadow(0 0 8px rgba(245,210,140,0.18));
}

.map-moving-unit.ally-moving img {
  filter:
    drop-shadow(0 4px 4px rgba(0,0,0,0.88))
    drop-shadow(0 0 8px rgba(80,150,255,0.55));
}

.map-moving-unit.enemy-moving img {
  filter:
    drop-shadow(0 4px 4px rgba(0,0,0,0.9))
    drop-shadow(0 0 8px rgba(255,80,80,0.48));
}

.map-moving-unit.boss-moving img {
  width: 100%;
  height: 100%;
  filter:
    drop-shadow(0 4px 5px rgba(0,0,0,0.92))
    drop-shadow(0 0 12px rgba(255,0,0,0.58))
    drop-shadow(0 0 8px rgba(255,210,100,0.36));
}

.map-moving-unit::after {
  content: "";
  position: absolute;
  left: 26%;
  right: 26%;
  bottom: 8%;
  height: 5px;
  border-radius: 999px;
  background: rgba(0,0,0,0.48);
  filter: blur(1px);
  animation: unitShadowMove 0.16s ease-in-out infinite alternate;
}

.moving-hidden {
  opacity: 0 !important;
}

@keyframes unitMapMove {
  0% {
    transform: translate(0, 0) scale(1);
  }

  38% {
    transform:
      translate(
        calc(var(--dx) * 38%),
        calc(var(--dy) * 38% - 8px)
      )
      scale(1.03);
  }

  100% {
    transform:
      translate(
        calc(var(--dx) * 100%),
        calc(var(--dy) * 100%)
      )
      scale(1);
  }
}

@keyframes unitMoveBob {
  from {
    transform: translateY(0) scale(1);
  }

  to {
    transform: translateY(-4px) scale(1.02);
  }
}

@keyframes unitShadowMove {
  from {
    opacity: 0.38;
    transform: scaleX(0.86);
  }

  to {
    opacity: 0.56;
    transform: scaleX(1.1);
  }
}

.tile {
  overflow: visible;
}

.battle-map {
  overflow: hidden;
}

@media (min-width: 650px) {
  .expanded-map .moving-unit-layer {
    inset: 12px;
  }
}

@media (max-width: 380px) {
  .moving-unit-layer {
    inset: 7px;
  }

  .map-moving-unit img {
    width: 88%;
    height: 88%;
  }
}



/* v0.47 타일 경로 이동 모션 */
.map-moving-unit {
  animation: unitMapStepMove var(--move-duration, 180ms) cubic-bezier(0.18, 0.82, 0.24, 1) forwards;
}

.map-moving-unit img {
  animation: unitStepWalk 0.12s ease-in-out infinite alternate;
}

.move-step-dust {
  position: absolute;
  left: 28%;
  right: 28%;
  bottom: 12%;
  height: 7px;
  border-radius: 999px;
  background:
    radial-gradient(circle, rgba(245,210,140,0.32), transparent 72%);
  filter: blur(1px);
  opacity: 0;
  animation: stepDust 0.18s ease-out infinite;
}

@keyframes unitMapStepMove {
  0% {
    transform: translate(0, 0) scale(1);
  }

  45% {
    transform:
      translate(
        calc(var(--dx) * 45%),
        calc(var(--dy) * 45% - 7px)
      )
      scale(1.035);
  }

  100% {
    transform:
      translate(
        calc(var(--dx) * 100%),
        calc(var(--dy) * 100%)
      )
      scale(1);
  }
}

@keyframes unitStepWalk {
  from {
    transform: translateY(0) rotate(-1.5deg) scale(1);
  }

  to {
    transform: translateY(-5px) rotate(1.5deg) scale(1.025);
  }
}

@keyframes stepDust {
  0% {
    opacity: 0;
    transform: scaleX(0.55);
  }

  45% {
    opacity: 0.55;
    transform: scaleX(1.05);
  }

  100% {
    opacity: 0;
    transform: scaleX(1.38);
  }
}



