    inset 0 0 18px rgba(245,210,140,0.06),
    0 0 14px rgba(245,210,140,0.10);
}

.cutscene-selector button strong {
  display: block;
  font-size: 14px;
}

.cutscene-selector button small {
  display: block;
  margin-top: 5px;
  color: #c8b8a8;
  font-size: 11px;
