}

.dk-hpbar {
  position: relative;
}

.dk-hpbar i {
  position: absolute;
  left: 0;
  top: 0;
}

.dk-hpbar .dk-hp-before {
  background: linear-gradient(to right, #ffb35b, #f5d28c);
