    radial-gradient(circle at 50% 20%, rgba(90,190,255,0.24), transparent 26%),
    linear-gradient(to bottom, #03101a 0%, #02060c 55%, #000 100%);
}

.dk-effect-ice .dk-slash {
  background:
    linear-gradient(to right, transparent, rgba(230,255,255,0.98), rgba(90,190,255,0.82), transparent);
  box-shadow: 0 0 18px rgba(90,190,255,0.52);
}

.dk-effect-ice .dk-spark,
.dk-effect-ice .dk-effect-orb {
  background:
    radial-gradient(circle, rgba(230,255,255,0.95), rgba(80,190,255,0.45) 48%, transparent 72%);
  box-shadow: 0 0 16px rgba(110,210,255,0.76);
}

.dk-effect-ice .dk-result-tag,
.dk-effect-ice .dk-effect-badge {
  border-color: rgba(120,220,255,0.44);
  color: #c9f3ff;
}

.dk-effect-shadow .dk-cutscene-bg {
  background:
    radial-gradient(circle at 50% 20%, rgba(140,30,255,0.30), transparent 24%),
    linear-gradient(to bottom, #0b0618 0%, #03010a 58%, #000 100%);
}

.dk-effect-shadow .dk-slash {
  background:
    linear-gradient(to right, transparent, rgba(230,190,255,0.98), rgba(130,45,255,0.82), rgba(255,40,90,0.34), transparent);
  box-shadow: 0 0 20px rgba(150,60,255,0.62);
}

.dk-effect-shadow .dk-spark,
.dk-effect-shadow .dk-effect-orb {
  background:
    radial-gradient(circle, rgba(235,190,255,0.95), rgba(130,45,255,0.52) 44%, transparent 72%);
  box-shadow: 0 0 18px rgba(150,60,255,0.82);
}

.dk-effect-shadow .dk-result-tag,
.dk-effect-shadow .dk-effect-badge {
  border-color: rgba(190,120,255,0.44);
  color: #e5d2ff;
}

.dk-effect-magic .dk-cutscene-bg {
  background:
    radial-gradient(circle at 50% 20%, rgba(60,120,255,0.30), transparent 24%),
