/* v0.78 보스 등장 / 2페이즈 컷씬 */
.boss-cutscene-overlay {
  position: fixed;
  inset: 0;
  z-index: 175;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 18px;
  background:
    radial-gradient(circle at center, rgba(160,0,0,0.24), transparent 58%),
    rgba(0,0,0,0.72);
  pointer-events: none;
  animation: bossOverlayIn 0.2s ease both;
}

.boss-cutscene-card {
  position: relative;
  width: min(430px, 94vw);
  min-height: 520px;
  border-radius: 30px;
  overflow: hidden;
  background:
    linear-gradient(to bottom, rgba(40,4,3,0.98), rgba(4,1,1,0.98));
  border: 1px solid rgba(245,210,140,0.34);
  box-shadow:
    0 0 48px rgba(0,0,0,0.76),
    0 0 38px rgba(255,40,20,0.28),
    inset 0 0 28px rgba(245,210,140,0.04);
  animation: bossCardIn 0.28s ease both;
}

.boss-cutscene-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 50% 18%, rgba(255,0,0,0.35), transparent 24%),
    linear-gradient(to bottom, #1a0202, #050000 62%, #000);
}

.boss-red-moon {
  position: absolute;
  left: 50%;
  top: 26px;
  width: 170px;
  height: 170px;
  transform: translateX(-50%);
  border-radius: 999px;
  background:
    radial-gradient(circle at 42% 36%, #ff4d4d, #870000 70%, #210000);
  box-shadow:
    0 0 48px rgba(255,0,0,0.46),
    0 0 96px rgba(255,0,0,0.24);
  opacity: 0.70;
}

.boss-aura {
  position: absolute;
  left: 50%;
  top: 188px;
  width: 320px;
  height: 320px;
  transform: translateX(-50%);
  border-radius: 999px;
  background:
    radial-gradient(circle, rgba(255,50,20,0.28), transparent 62%);
  animation: bossAuraPulse 0.82s ease-in-out infinite alternate;
}

.boss-cutscene-label {
  position: relative;
  z-index: 2;
  margin: 22px auto 0;
  width: fit-content;
  padding: 8px 18px;
  border-radius: 999px;
  color: #f5d28c;
  font-size: 14px;
  font-weight: 900;
  letter-spacing: 2px;
  background: rgba(0,0,0,0.38);
  border: 1px solid rgba(245,210,140,0.24);
}

.boss-cutscene-stage {
  position: relative;
  z-index: 2;
  height: 285px;
  display: flex;
  align-items: flex-end;
  justify-content: center;
}

.boss-cutscene-stage img {
  position: relative;
  z-index: 3;
  width: 245px;
  height: 245px;
  object-fit: contain;
  filter:
    drop-shadow(0 12px 10px rgba(0,0,0,0.85))
    drop-shadow(0 0 24px rgba(255,40,20,0.38));
  animation: bossRise 0.58s ease both;
}

.boss-cutscene-flare {
  position: absolute;
  bottom: 20px;
  width: 330px;
  height: 70px;
  border-radius: 999px;
  background:
    radial-gradient(ellipse at center, rgba(245,210,140,0.26), rgba(255,0,0,0.10) 56%, transparent);
  filter: blur(2px);
}

.boss-cutscene-info {
  position: relative;
  z-index: 3;
  margin: 0 20px 22px;
  padding: 18px;
  border-radius: 22px;
  background:
    linear-gradient(to bottom, rgba(40,8,5,0.86), rgba(5,1,1,0.92));
  border: 1px solid rgba(245,210,140,0.18);
  text-align: center;
}

.boss-cutscene-info h2 {
  color: #f5d28c;
  font-size: 26px;
  margin: 0;
}

.boss-cutscene-info p {
  margin: 9px 0 0;
  color: #d8c8b8;
  font-size: 13px;
  line-height: 1.55;
}

.boss-stat-row {
  margin-top: 13px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.boss-stat-row span {
  padding: 8px 5px;
  border-radius: 12px;
  background: rgba(0,0,0,0.25);
  border: 1px solid rgba(255,255,255,0.05);
  color: #fff0c8;
  font-size: 11px;
  font-weight: 900;
}

.boss-phase2 .boss-cutscene-card {
  box-shadow:
    0 0 52px rgba(0,0,0,0.80),
    0 0 44px rgba(190,70,255,0.34),
    inset 0 0 32px rgba(210,140,255,0.08);
}

.boss-phase2 .boss-cutscene-bg {
  background:
    radial-gradient(circle at 50% 18%, rgba(140,40,255,0.36), transparent 24%),
    linear-gradient(to bottom, #0c0618, #03000a 62%, #000);
}

.boss-phase2 .boss-aura {
  background:
    radial-gradient(circle, rgba(180,70,255,0.34), transparent 62%);
}

.boss-phase2 .boss-cutscene-stage img {
  filter:
    drop-shadow(0 12px 10px rgba(0,0,0,0.86))
    drop-shadow(0 0 28px rgba(190,70,255,0.58));
  animation: bossPhaseRise 0.7s ease both;
}

@keyframes bossOverlayIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes bossCardIn {
  from { opacity: 0; transform: scale(0.94) translateY(18px); }
  to { opacity: 1; transform: scale(1) translateY(0); }
}

@keyframes bossRise {
  from { opacity: 0; transform: translateY(50px) scale(0.88); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

@keyframes bossPhaseRise {
  0% { opacity: 0.4; transform: translateY(20px) scale(0.92); filter: brightness(1); }
  45% { opacity: 1; transform: translateY(-12px) scale(1.08); filter: brightness(1.8); }
  100% { opacity: 1; transform: translateY(0) scale(1); filter: brightness(1); }
}

@keyframes bossAuraPulse {
  from { opacity: 0.52; transform: translateX(-50%) scale(0.92); }
  to { opacity: 1; transform: translateX(-50%) scale(1.08); }
}

@media (max-width: 380px) {
  .boss-cutscene-card {
    min-height: 470px;
  }

  .boss-cutscene-stage {
    height: 248px;
  }

  .boss-cutscene-stage img {
    width: 205px;
    height: 205px;
  }

  .boss-cutscene-info h2 {
    font-size: 22px;
  }

  .boss-stat-row {
    grid-template-columns: 1fr;
  }
}



