@keyframes dkCinematicAttacker {
  0% { transform: translateX(-42px) scale(0.96); opacity: 0.76; filter: brightness(0.88); }
  20% { transform: translateX(-22px) scale(0.99); opacity: 1; filter: brightness(1.05); }
  42% { transform: translateX(92px) translateY(-3px) scale(1.08); filter: brightness(1.35); }
  56% { transform: translateX(120px) translateY(2px) scale(1.1); filter: brightness(1.5); }
  72% { transform: translateX(22px) scale(1.02); filter: brightness(1.08); }
  100% { transform: translateX(0) scale(1); opacity: 1; filter: brightness(1); }
}

@keyframes dkCinematicDefender {
  0%, 42% { transform: translateX(0) rotate(0deg); filter: brightness(1); }
  50% { transform: translateX(24px) rotate(3deg); filter: brightness(1.7) saturate(1.25); }
  58% { transform: translateX(-12px) rotate(-2deg); filter: brightness(1.25); }
  68% { transform: translateX(8px) rotate(1deg); }
  100% { transform: translateX(0) rotate(0deg); filter: brightness(1); }
}

@keyframes dkCinematicMissAttacker {
  0% { transform: translateX(-36px) scale(0.97); opacity: 0.78; }
  34% { transform: translateX(78px) translateY(-2px) scale(1.06); opacity: 1; }
  52% { transform: translateX(126px) translateY(-4px) scale(1.04); filter: brightness(1.24); }
  70% { transform: translateX(28px) scale(1.01); }
  100% { transform: translateX(0) scale(1); }
}

@keyframes dkCinematicEvade {
  0%, 34% { transform: translateX(0); opacity: 1; }
  48% { transform: translateX(30px) translateY(-8px); opacity: 0.54; filter: brightness(1.35); }
  64% { transform: translateX(-4px); opacity: 1; }
  100% { transform: translateX(0); opacity: 1; }
}

@keyframes dkCasterPose {
  0% { transform: translateX(-24px); opacity: 0.8; }
  22% { transform: translateX(0) translateY(-4px); opacity: 1; filter: brightness(1.2); }
  54% { transform: translateX(10px) translateY(-8px) scale(1.03); filter: brightness(1.38); }
  100% { transform: translateX(0) translateY(0) scale(1); filter: brightness(1); }
}

@keyframes dkHealedTarget {
  0%, 42% { transform: translateY(0); filter: brightness(1); }
  58% { transform: translateY(-8px); filter: brightness(1.5) saturate(1.2); }
  100% { transform: translateY(0); filter: brightness(1); }
}

@keyframes dkAfterimageSweep {
  0%, 18% { opacity: 0; transform: translateX(-95px) scale(0.82); }
  36% { opacity: 0.58; transform: translateX(-18px) scale(1); }
  56% { opacity: 0.2; transform: translateX(74px) scale(1.08); }
  72%, 100% { opacity: 0; transform: translateX(-50%) scale(0.9); }
}

@keyframes dkCastAuraPulse {
  0%, 14% { opacity: 0; transform: translateX(-50%) scale(0.72); }
  28% { opacity: 0.82; transform: translateX(-50%) scale(1); }
  52% { opacity: 0.46; transform: translateX(-50%) scale(1.24); }
  100% { opacity: 0; transform: translateX(-50%) scale(1.36); }
}

@keyframes dkWeaponDraw {
  0%, 24% { opacity: 0; transform: rotate(-42deg) translateX(-42px) scaleX(0.08); }
  36% { opacity: 0.96; transform: rotate(-28deg) translateX(0) scaleX(0.8); }
  48% { opacity: 1; transform: rotate(-16deg) translateX(76px) scaleX(1.32); }
  62% { opacity: 0.75; transform: rotate(-8deg) translateX(138px) scaleX(0.96); }
  76%, 100% { opacity: 0; transform: rotate(-8deg) translateX(172px) scaleX(0.5); }
}

@keyframes dkWeaponTrail {
  0%, 28% { opacity: 0; transform: rotate(-38deg) translateX(-38px) scale(0.35); }
  44% { opacity: 0.9; transform: rotate(-22deg) translateX(46px) scale(0.98); }
  64% { opacity: 0.22; transform: rotate(-10deg) translateX(132px) scale(1.18); }
  100% { opacity: 0; transform: rotate(-10deg) translateX(172px) scale(1.26); }
}

@keyframes dkHitGuardFlash {
  0%, 42% { opacity: 0; transform: translateX(-50%) scale(0.52); }
  51% { opacity: 0.82; transform: translateX(-50%) scale(1.06); }
  66% { opacity: 0.28; transform: translateX(-50%) scale(1.24); }
  100% { opacity: 0; transform: translateX(-50%) scale(1.36); }
}

@keyframes dkImpactFlash {
  0%, 42% { opacity: 0; transform: translate(-50%, -50%) scale(0.2); }
  50% { opacity: 0.98; transform: translate(-50%, -50%) scale(1.05); }
  66% { opacity: 0.24; transform: translate(-50%, -50%) scale(1.48); }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(1.7); }
