@keyframes dkArrowProjectile {
  0%, 24% { opacity: 0; transform: rotate(-8deg) translateX(-86px) scaleX(0.28); }
  36% { opacity: 1; transform: rotate(-8deg) translateX(-16px) scaleX(0.72); }
  52% { opacity: 1; transform: rotate(-8deg) translateX(132px) scaleX(1.08); }
