/* v1.99.5 character-body combat motion */
.dk-cutscene-card {
  --dk-cutscene-ms: 1880ms;
  --dk-impact-start: 0.68s;
}

.dk-fighter img {
  transform-origin: 50% 96%;
  will-change: transform, filter, opacity;
}

.dk-attacker {
  animation: dkV1995AttackerStage var(--dk-cutscene-ms, 1880ms) cubic-bezier(0.22, 0.72, 0.18, 1) both !important;
}

.dk-attacker img {
  animation: dkV1995AttackerBody var(--dk-cutscene-ms, 1880ms) cubic-bezier(0.2, 0.7, 0.18, 1) both !important;
}

.dk-defender {
  animation: dkV1995DefenderStage var(--dk-cutscene-ms, 1880ms) ease-out both !important;
}

.dk-defender img {
  animation: dkV1995DefenderBody var(--dk-cutscene-ms, 1880ms) ease-out both !important;
}

.dk-platform {
  animation: dkV1995PlatformPulse var(--dk-cutscene-ms, 1880ms) ease-out both;
}

.dk-cutscene-weapon {
  animation: dkV1995WeaponFollow var(--dk-cutscene-ms, 1880ms) ease-out both !important;
}

.dk-cutscene-trail {
  animation: dkV1995TrailFollow var(--dk-cutscene-ms, 1880ms) ease-out both !important;
}

.dk-slash {
  animation: dkV1995Slash 0.84s ease var(--dk-impact-start, 0.68s) both !important;
}

.dk-spark {
  animation: dkV1995Spark 0.72s ease calc(var(--dk-impact-start, 0.68s) + 0.08s) both !important;
}

.dk-spark-b {
  animation: dkV1995ShockRing 0.82s ease calc(var(--dk-impact-start, 0.68s) + 0.14s) both !important;
}

.dk-impact-layer b {
  animation: dkV1995DamageText 0.86s ease calc(var(--dk-impact-start, 0.68s) + 0.16s) both !important;
}

.dk-hit-guard,
.dk-motion-impact-flash {
  animation: dkV1995ImpactBodyFlash var(--dk-cutscene-ms, 1880ms) ease-out both !important;
}

.dk-motion-arrow .dk-attacker {
  animation: dkV1995ArcherStage var(--dk-cutscene-ms, 1880ms) ease both !important;
}

.dk-motion-arrow .dk-attacker img {
  animation: dkV1995ArcherBody var(--dk-cutscene-ms, 1880ms) ease both !important;
}

.dk-motion-arrow .dk-defender img {
  animation: dkV1995DefenderPierced var(--dk-cutscene-ms, 1880ms) ease-out both !important;
}

.dk-motion-fire .dk-attacker,
.dk-motion-ice .dk-attacker,
.dk-motion-shadow .dk-attacker,
.dk-motion-aura .dk-attacker {
  animation: dkV1995CasterStage var(--dk-cutscene-ms, 1880ms) ease both !important;
}

.dk-motion-fire .dk-attacker img,
.dk-motion-ice .dk-attacker img,
.dk-motion-shadow .dk-attacker img,
.dk-motion-aura .dk-attacker img {
  animation: dkV1995CasterBody var(--dk-cutscene-ms, 1880ms) ease both !important;
}

.dk-motion-fire .dk-defender img,
.dk-motion-ice .dk-defender img,
.dk-motion-shadow .dk-defender img,
.dk-motion-aura .dk-defender img {
  animation: dkV1995DefenderSpellHit var(--dk-cutscene-ms, 1880ms) ease-out both !important;
}

.dk-motion-heal .dk-attacker,
.heal-cutscene .dk-attacker {
  animation: dkV1995HealerStage var(--dk-cutscene-ms, 1880ms) ease both !important;
}

.dk-motion-heal .dk-attacker img,
.heal-cutscene .dk-attacker img {
  animation: dkV1995HealerBody var(--dk-cutscene-ms, 1880ms) ease both !important;
}

.dk-motion-heal .dk-defender img,
.heal-cutscene .dk-defender img {
  animation: dkV1995HealedBody var(--dk-cutscene-ms, 1880ms) ease both !important;
}

.dk-motion-guard .dk-attacker img {
  animation: dkV1995GuardBody var(--dk-cutscene-ms, 1880ms) ease both !important;
}

.dk-motion-bite .dk-attacker img {
  animation: dkV1995BiteBody var(--dk-cutscene-ms, 1880ms) ease both !important;
}

.miss-cutscene .dk-attacker {
  animation: dkV1995MissStage var(--dk-cutscene-ms, 1880ms) ease both !important;
}

.miss-cutscene .dk-attacker img {
  animation: dkV1995MissBody var(--dk-cutscene-ms, 1880ms) ease both !important;
}

.miss-cutscene .dk-defender img {
  animation: dkV1995EvadeBody var(--dk-cutscene-ms, 1880ms) ease both !important;
}

.finish-cutscene .dk-attacker img {
  animation: dkV1995FinishAttackerBody var(--dk-cutscene-ms, 2240ms) cubic-bezier(0.18, 0.74, 0.14, 1) both !important;
}

.finish-cutscene .dk-defender img {
  animation: dkV1995FinishDefenderBody var(--dk-cutscene-ms, 2240ms) ease-out both !important;
}

.finish-cutscene .dk-finish-beam {
  animation: dkV1995FinishPulse var(--dk-cutscene-ms, 2240ms) ease-out both !important;
}

