/* v0.93 스테이지 목표 다양화 */
.stage-mission-badge {
  margin-top: 7px;
  display: inline-flex;
  padding: 5px 9px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 900;
  border: 1px solid rgba(120,255,180,0.18);
  background: rgba(0,0,0,0.24);
  color: #b8ffdd;
}

.briefing-mission-row {
  margin-top: 10px;
  padding: 11px;
  display: grid;
  grid-template-columns: 62px 1fr;
  gap: 5px 9px;
  align-items: center;
  border-radius: 16px;
  background:
    linear-gradient(to right, rgba(16, 58, 44, 0.76), rgba(5, 20, 14, 0.86));
  border: 1px solid rgba(120,255,180,0.16);
}

.briefing-mission-row span {
  grid-row: 1 / span 2;
  color: #b8ffdd;
  font-size: 11px;
  font-weight: 900;
}

.briefing-mission-row strong {
  color: #f5d28c;
  font-size: 14px;
}

.briefing-mission-row em {
  color: #c8d8c8;
  font-size: 11px;
  font-style: normal;
