}

.tactical-goal-mini.secondary {
  margin-top: 6px;
  color: #a99a8d;
  font-size: 11px;
}

.mission-result-card {
  margin-top: 14px;
  padding: 14px;
  border-radius: 18px;
  background:
    radial-gradient(circle at top left, rgba(120,255,180,0.15), transparent 48%),
    rgba(0,0,0,0.30);
  border: 1px solid rgba(120,255,180,0.22);
}

.mission-result-title {
  color: #b8ffdd;
  font-size: 14px;
  font-weight: 900;
}

.mission-result-card strong {
  display: block;
  margin-top: 7px;
  color: #f5d28c;
