.node-body strong {
  display: block;
  color: #f5d28c;
  font-size: 15px;
}

.node-body em {
  display: block;
  margin-top: 5px;
  color: #b8ffdd;
  font-size: 12px;
  font-style: normal;
  font-weight: 900;
