/* v0.99 출시 전 UI polish / 로딩 / 버전 표시 */
.launch-loading-screen {
  position: fixed;
  inset: 0;
  z-index: 999;
  display: flex;
  align-items: center;
  justify-content: center;
  background:
    radial-gradient(circle at center, rgba(120, 20, 10, 0.22), transparent 58%),
    linear-gradient(to bottom, #080201, #000);
  animation: launchFadeOut 0.28s ease 0.68s both;
}

.launch-loading-card {
  width: min(320px, 82vw);
  padding: 26px 22px;
  border-radius: 28px;
  background:
    radial-gradient(circle at top, rgba(245,210,140,0.16), transparent 58%),
    rgba(20, 8, 4, 0.92);
  border: 1px solid rgba(245,210,140,0.22);
  box-shadow:
    0 0 42px rgba(0,0,0,0.7),
    inset 0 0 24px rgba(245,210,140,0.04);
  text-align: center;
}

.launch-loading-card img {
  width: 120px;
  height: auto;
  object-fit: contain;
  filter: drop-shadow(0 8px 12px rgba(0,0,0,0.55));
}

.launch-loading-card strong {
  display: block;
  margin-top: 12px;
  color: #f5d28c;
  font-size: 24px;
  letter-spacing: 2px;
}

.launch-loading-card span {
  display: block;
  margin-top: 8px;
  color: #d8c8b8;
  font-size: 13px;
}

.launch-loading-bar {
  margin-top: 18px;
  height: 8px;
  border-radius: 999px;
  overflow: hidden;
  background: rgba(0,0,0,0.42);
  border: 1px solid rgba(255,255,255,0.06);
}

.launch-loading-bar i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(to right, #8a2b18, #f5d28c);
  animation: launchLoading 0.72s ease both;
}

.version-badge {
  position: fixed;
  right: 10px;
  bottom: 10px;
  z-index: 40;
  padding: 6px 10px;
  border-radius: 999px;
  color: #bfa384;
  font-size: 10px;
  font-weight: 900;
  background: rgba(0,0,0,0.34);
  border: 1px solid rgba(245,210,140,0.12);
  backdrop-filter: blur(8px);
  pointer-events: none;
}

.settings-version-label {
  display: inline-flex;
  margin-top: 5px;
  color: #bfa384;
  font-size: 12px;
  font-weight: 900;
}

.promo-version-line,
.menu-version-line {
  margin-top: 10px;
  color: #9f9080;
  font-size: 11px;
  text-align: center;
  font-weight: 900;
  letter-spacing: 1px;
}

.menu-version-line {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 12px;
  pointer-events: none;
}

button {
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible {
  outline: 2px solid rgba(245,210,140,0.82);
  outline-offset: 2px;
}

.battle-card,
.result-card,
.stage-briefing-card,
.deployment-readiness-card,
.deployment-equipment-card,
.battle-objective-panel,
.world-region-card,
.camp-tab-panel,
.settings-card {
  transform: translateZ(0);
}

@keyframes launchLoading {
  from { width: 0%; }
  to { width: 100%; }
}

@keyframes launchFadeOut {
  to {
    opacity: 0;
    visibility: hidden;
  }
}

@media (max-width: 380px) {
  .version-badge {
    right: 7px;
    bottom: 7px;
    font-size: 9px;
    padding: 5px 8px;
  }

  .launch-loading-card {
    padding: 22px 18px;
  }

  .launch-loading-card img {
    width: 100px;
  }

  .menu-version-line {
    bottom: 6px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .launch-loading-screen,
  .launch-loading-bar i,
  .combat-cutscene-card,
  .boss-cutscene-card,
  .stage-banner,
  .damage-popup,
  .effect {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
  }
}



