    radial-gradient(circle at top, rgba(40, 120, 90, 0.16), transparent 44%),
    linear-gradient(to bottom, #07120d, #020403 72%, #000);
}

.qa-summary-card {
  margin-top: 14px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 9px;
}

.qa-summary-card div {
  padding: 12px;
  border-radius: 16px;
  background: rgba(0,0,0,0.26);
  border: 1px solid rgba(120,255,180,0.12);
}

.qa-summary-card span {
  display: block;
  color: #b9d8c8;
  font-size: 11px;
  font-weight: 900;
}

.qa-summary-card strong {
  display: block;
  margin-top: 6px;
  color: #b8ffdd;
  font-size: 15px;
}

.qa-checklist-card,
.qa-diagnostics-card {
  margin-top: 15px;
  padding: 15px;
  border-radius: 22px;
  background:
    radial-gradient(circle at top left, rgba(120,255,180,0.10), transparent 48%),
    rgba(0,0,0,0.24);
  border: 1px solid rgba(120,255,180,0.14);
}

.qa-checklist-card h2,
.qa-diagnostics-card h2 {
  color: #b8ffdd;
  font-size: 18px;
  margin-bottom: 12px;
}

.qa-checklist-grid {
  display: grid;
  gap: 8px;
}

.qa-checklist-grid button {
  min-height: 54px;
  border: none;
  border-radius: 15px;
  padding: 9px;
  display: grid;
  grid-template-columns: 28px 1fr;
  gap: 9px;
  align-items: center;
  background:
    linear-gradient(to bottom, rgba(14, 28, 22, 0.92), rgba(4, 12, 8, 0.96));
  color: #d8e8d8;
  border: 1px solid rgba(120,255,180,0.10);
  text-align: left;
}

.qa-checklist-grid button.checked {
  border-color: rgba(120,255,180,0.32);
  background:
    radial-gradient(circle at top left, rgba(120,255,180,0.12), transparent 48%),
    linear-gradient(to bottom, rgba(18, 60, 42, 0.92), rgba(4, 18, 10, 0.96));
}

.qa-checklist-grid button > span {
  width: 28px;
  height: 28px;
  border-radius: 999px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0,0,0,0.26);
  color: #b8ffdd;
  border: 1px solid rgba(120,255,180,0.18);
