  .qa-actions-grid,
  .qa-shortcut-grid {
    grid-template-columns: 1fr;
  }
}



/* v1.02 피드백 트래커 / QA 노트 */
.feedback-type-row {
  margin-bottom: 10px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}

.feedback-type-row button {
  min-height: 36px;
  border: none;
  border-radius: 999px;
  background:
    linear-gradient(to bottom, rgba(26, 34, 48, 0.96), rgba(8, 12, 18, 0.98));
  color: #c8d8e8;
  font-size: 12px;
  font-weight: 900;
  border: 1px solid rgba(130,180,255,0.14);
}

.feedback-type-row button.selected {
  color: #b8ffdd;
  border-color: rgba(120,255,180,0.28);
