}

.feedback-list-card {
  margin-top: 14px;
  padding: 12px;
  border-radius: 18px;
  background: rgba(0,0,0,0.22);
  border: 1px solid rgba(120,255,180,0.10);
}

.feedback-list-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.feedback-list-head strong {
  color: #b8ffdd;
  font-size: 15px;
}

.feedback-list-head span {
  color: #c8d8c8;
  font-size: 12px;
  font-weight: 900;
}

.feedback-list {
  margin-top: 10px;
  display: grid;
  gap: 9px;
}

.feedback-item {
  padding: 11px;
  border-radius: 15px;
  background:
    linear-gradient(to bottom, rgba(18, 30, 24, 0.78), rgba(5, 12, 8, 0.9));
  border: 1px solid rgba(120,255,180,0.10);
}

.feedback-item.status-fixed {
  border-color: rgba(120,255,180,0.28);
}

.feedback-item.status-later {
  border-color: rgba(245,210,140,0.22);
}

.feedback-item > div:first-child {
  display: flex;
  justify-content: space-between;
  gap: 8px;
}

.feedback-item strong {
  color: #f5d28c;
  font-size: 13px;
}

.feedback-item span {
  color: #9fb8a8;
  font-size: 10px;
  text-align: right;
}

