  margin: 8px 0 0;
  color: #d8e8d8;
  font-size: 12px;
  line-height: 1.45;
  word-break: keep-all;
}

.feedback-status-row {
  margin-top: 10px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 7px;
}

.feedback-status-row button {
  min-height: 32px;
  border: none;
  border-radius: 999px;
  background: rgba(0,0,0,0.25);
  color: #c8d8c8;
  font-size: 11px;
  font-weight: 900;
  border: 1px solid rgba(255,255,255,0.06);
}

.feedback-status-row button.selected {
  color: #b8ffdd;
  border-color: rgba(120,255,180,0.24);
}

.feedback-empty {
  margin-top: 10px;
  color: #9fb8a8;
  font-size: 12px;
  text-align: center;
  padding: 16px 0;
}

.feedback-clear-btn {
  margin-top: 11px;
  width: 100%;
  min-height: 38px;
  border: none;
  border-radius: 14px;
  background:
    linear-gradient(to bottom, rgba(120, 38, 32, 0.96), rgba(42, 8, 6, 0.98));
  color: #ffd6d0;
  font-weight: 900;
  border: 1px solid rgba(255,120,100,0.20);
}

@media (max-width: 380px) {
  .feedback-type-row,
  .feedback-status-row {
    grid-template-columns: repeat(2, 1fr);
  }

  .feedback-item > div:first-child {
    display: block;
  }

  .feedback-item span {
    display: block;
    margin-top: 4px;
    text-align: left;
  }
}



