/* v1.09 천수 도감 / 컬렉션 */
.codex-screen{min-height:100dvh;padding:20px;color:#f4ead8;background:radial-gradient(circle at top,rgba(245,210,140,.13),transparent 44%),linear-gradient(to bottom,#100603,#030101 72%,#000)}
.codex-search-card{margin-top:14px;padding:13px;border-radius:20px;background:rgba(0,0,0,.24);border:1px solid rgba(245,210,140,.13)}
.codex-search-card input{width:100%;min-height:42px;border:none;border-radius:14px;padding:0 13px;background:rgba(0,0,0,.30);color:#f4ead8;border:1px solid rgba(255,255,255,.06);font-family:inherit}
.codex-category-row{margin-top:10px;display:flex;gap:7px;overflow-x:auto;padding-bottom:3px;-webkit-overflow-scrolling:touch}
.codex-category-row button{flex:0 0 auto;min-height:34px;padding:0 12px;border-radius:999px;border:none;background:linear-gradient(to bottom,rgba(34,18,10,.94),rgba(9,4,2,.96));color:#d8c8b8;font-size:12px;font-weight:900;border:1px solid rgba(245,210,140,.12)}
