.profile-actions button{min-height:42px;border:none;border-radius:15px;background:linear-gradient(to bottom,rgba(38,58,92,.96),rgba(10,18,34,.98));color:#d7e8ff;font-weight:900;border:1px solid rgba(130,180,255,.18)}
