/* v1.50.6 이동 모션 / 캐릭터 걷기 연출 강화 */
.map-moving-unit {
  z-index: 80 !important;
  overflow: visible !important;
}

.map-moving-unit img {
  transform-origin: 50% 88%;
  animation:
    unitWalkBounce 0.18s ease-in-out infinite alternate,
    unitWalkTilt 0.36s ease-in-out infinite;
}

.map-moving-unit.moving-left img {
  transform: scaleX(-1);
}

.map-moving-unit.moving-left img,
.map-moving-unit.moving-right img {
  animation:
    unitWalkBounceX 0.18s ease-in-out infinite alternate,
    unitWalkTilt 0.36s ease-in-out infinite;
}

.map-moving-unit.moving-up img {
  filter:
    drop-shadow(0 5px 5px rgba(0,0,0,0.9))
    brightness(0.94);
}

.map-moving-unit.moving-down img {
  filter:
    drop-shadow(0 5px 5px rgba(0,0,0,0.9))
    drop-shadow(0 0 9px rgba(245,210,140,0.22))
    brightness(1.04);
}

.moving-unit-fallback {
  position: absolute;
  inset: 0;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 26px;
  filter:
    drop-shadow(0 4px 4px rgba(0,0,0,0.85))
    drop-shadow(0 0 8px rgba(245,210,140,0.25));
}

.map-moving-unit img {
  position: relative;
  z-index: 2;
}

.move-trail {
  position: absolute;
  left: 18%;
  right: 18%;
  top: 55%;
  height: 12%;
  border-radius: 999px;
  z-index: 0;
  background:
    radial-gradient(circle, rgba(245,210,140,0.30), rgba(245,210,140,0.06) 60%, transparent 72%);
  filter: blur(1.4px);
  opacity: 0.78;
  animation: moveTrailFade var(--move-duration, 460ms) ease-out forwards;
}

.move-trail-b {
  animation-delay: 80ms;
  opacity: 0.55;
  transform: scaleX(0.75);
}

.map-moving-unit.ally-moving .move-trail {
  background:
    radial-gradient(circle, rgba(90,170,255,0.36), rgba(90,170,255,0.07) 60%, transparent 72%);
}

.map-moving-unit.enemy-moving .move-trail {
  background:
    radial-gradient(circle, rgba(255,90,100,0.34), rgba(255,90,100,0.07) 60%, transparent 72%);
}

.map-moving-unit.boss-moving .move-trail {
  background:
    radial-gradient(circle, rgba(255,210,80,0.40), rgba(255,210,80,0.08) 60%, transparent 72%);
}

.move-step-dust {
  position: absolute;
  z-index: 0;
  width: 26%;
  height: 14%;
  left: 36%;
  bottom: 2%;
  border-radius: 999px;
  background:
    radial-gradient(circle, rgba(160,120,70,0.55), rgba(160,120,70,0.12) 55%, transparent 72%);
  filter: blur(1px);
  animation: dustStepPop 0.24s ease-in-out infinite;
}

.move-step-dust.dust-b {
  animation-delay: 0.12s;
  left: 46%;
  opacity: 0.72;
}

.move-motion-ring {
  position: absolute;
  left: 20%;
  right: 20%;
  bottom: 0%;
  height: 18%;
  border-radius: 999px;
  border: 1px solid rgba(245,210,140,0.18);
  transform: scaleX(0.80);
  animation: moveRingPulse 0.28s ease-in-out infinite alternate;
}

.moving-source-shadow::after {
  content: "";
  position: absolute;
  left: 22%;
  right: 22%;
  bottom: 16%;
  height: 8px;
  border-radius: 999px;
  background: rgba(0,0,0,0.38);
  filter: blur(1px);
  opacity: 1;
}

.move-tile::after {
  content: "";
  position: absolute;
  inset: 18%;
  border-radius: 999px;
  background: rgba(90,170,255,0.16);
  animation: moveTilePulse 0.75s ease-in-out infinite alternate;
}

@keyframes unitWalkBounce {
  0% {
    transform: translateY(0) scale(1.00);
  }
  100% {
    transform: translateY(-6px) scale(1.035);
  }
}

@keyframes unitWalkBounceX {
  0% {
    transform: translateY(0) scale(1.00);
  }
  100% {
    transform: translateY(-5px) scale(1.04);
  }
}

@keyframes unitWalkTilt {
  0%, 100% {
    rotate: -2deg;
  }
  50% {
    rotate: 2deg;
  }
}

@keyframes moveTrailFade {
  0% {
    opacity: 0;
    transform: translate(calc(var(--dx) * -12%), calc(var(--dy) * -12%)) scale(0.72);
  }
  36% {
    opacity: 0.78;
  }
  100% {
    opacity: 0;
    transform: translate(calc(var(--dx) * -42%), calc(var(--dy) * -42%)) scale(1.18);
  }
}

@keyframes dustStepPop {
  0% {
    opacity: 0;
    transform: scale(0.55) translateY(0);
  }
  48% {
    opacity: 0.8;
  }
  100% {
    opacity: 0;
    transform: scale(1.25) translateY(4px);
  }
}

@keyframes moveRingPulse {
  from {
    opacity: 0.32;
    transform: scaleX(0.72);
  }
  to {
    opacity: 0.72;
    transform: scaleX(1.08);
  }
}

@keyframes moveTilePulse {
  from {
    opacity: 0.20;
    transform: scale(0.82);
  }
  to {
    opacity: 0.62;
    transform: scale(1.06);
  }
}

/* 이동 중 원래 위치가 순간이동처럼 비지 않도록 잔상 느낌 유지 */
.moving-hidden {
  opacity: 0.18 !important;
  filter: grayscale(0.6) blur(0.2px);
}

.map-moving-unit.boss-moving img {
  animation:
    unitWalkBounce 0.22s ease-in-out infinite alternate,
    unitBossMoveGlow 0.55s ease-in-out infinite alternate;
}

@keyframes unitBossMoveGlow {
  from {
    filter:
      drop-shadow(0 4px 5px rgba(0,0,0,0.92))
      drop-shadow(0 0 10px rgba(255,0,0,0.45))
      drop-shadow(0 0 6px rgba(255,210,100,0.26));
  }
  to {
    filter:
      drop-shadow(0 4px 5px rgba(0,0,0,0.92))
      drop-shadow(0 0 16px rgba(255,0,0,0.62))
      drop-shadow(0 0 10px rgba(255,210,100,0.42));
  }
}

@media (max-width: 430px) {
  .moving-unit-fallback {
    font-size: 22px;
  }

  .map-moving-unit img {
    width: 106% !important;
    height: 106% !important;
  }
}


/* v1.50.7 공격 모션 / 타격 반응 강화 */
.effect-attack-motion,
.effect-counter-motion,
.effect-assist-motion,
.effect-cast-motion {
  inset: -8% !important;
  z-index: 12 !important;
}

.effect-attack-motion::before,
.effect-counter-motion::before,
.effect-assist-motion::before {
  content: "";
  position: absolute;
  left: 18%;
  top: 18%;
  width: 64%;
  height: 64%;
  border-radius: 999px;
  background:
    radial-gradient(circle, rgba(245,210,140,0.36), rgba(245,210,140,0.08) 55%, transparent 74%);
  border: 1px solid rgba(245,210,140,0.18);
  animation: attackMotionPulse 0.42s ease-out forwards;
}

.effect-attack-motion::after,
.effect-counter-motion::after,
.effect-assist-motion::after {
  content: "";
  position: absolute;
  left: 14%;
  top: 46%;
  width: 72%;
  height: 8px;
  border-radius: 999px;
  background:
    linear-gradient(to right, transparent, rgba(255,255,255,0.95), rgba(245,210,140,0.85), transparent);
  box-shadow:
    0 0 12px rgba(255,255,255,0.72),
    0 0 22px rgba(245,210,140,0.36);
  transform: rotate(-18deg) scaleX(0);
  animation: attackMotionSwipe 0.42s ease-out forwards;
}

.effect-counter-motion::after {
  transform: rotate(24deg) scaleX(0);
  background:
    linear-gradient(to right, transparent, rgba(180,220,255,0.95), rgba(255,255,255,0.95), transparent);
}

.effect-assist-motion::after {
  background:
    linear-gradient(to right, transparent, rgba(185,255,220,0.95), rgba(255,255,255,0.95), transparent);
}

.effect-cast-motion::before {
  content: "";
  position: absolute;
  inset: 12%;
  border-radius: 999px;
  border: 2px solid rgba(180,110,255,0.34);
  box-shadow:
    0 0 18px rgba(180,110,255,0.35),
    inset 0 0 18px rgba(180,110,255,0.12);
  animation: castCircle 0.58s ease-out forwards;
}

.effect-cast-motion::after {
  content: "";
  position: absolute;
  left: 42%;
  top: 8%;
  width: 16%;
  height: 84%;
  border-radius: 999px;
  background:
    linear-gradient(to bottom, transparent, rgba(255,255,255,0.95), rgba(180,110,255,0.75), transparent);
  filter: blur(0.2px);
  animation: castBeam 0.58s ease-out forwards;
}

.effect-impact-ring::before,
.effect-evade-ring::before {
  content: "";
  position: absolute;
  inset: 18%;
  border-radius: 999px;
  border: 2px solid rgba(255,255,255,0.62);
  box-shadow:
    0 0 12px rgba(255,255,255,0.55),
    inset 0 0 16px rgba(255,255,255,0.18);
  animation: impactRing 0.48s ease-out forwards;
}

.effect-impact-ring::after {
  content: "";
  position: absolute;
  left: 10%;
  right: 10%;
  top: 48%;
  height: 10px;
  border-radius: 999px;
  background:
    linear-gradient(to right, transparent, rgba(255,255,255,0.96), rgba(255,90,80,0.88), transparent);
  transform: rotate(18deg) scaleX(0);
  animation: impactSpark 0.44s ease-out forwards;
}

.effect-evade-ring::before {
  border-color: rgba(160,210,255,0.60);
  box-shadow:
    0 0 12px rgba(160,210,255,0.55),
    inset 0 0 16px rgba(160,210,255,0.18);
  animation: evadeRing 0.44s ease-out forwards;
}

.attack-tile {
  overflow: visible !important;
}

.attack-target-mark {
  position: absolute;
  left: 50%;
  top: -10px;
  transform: translateX(-50%);
  padding: 2px 6px;
  border-radius: 999px;
  background: rgba(255,60,70,0.80);
  color: white;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.4px;
  border: 1px solid rgba(255,255,255,0.42);
  box-shadow: 0 0 8px rgba(255,60,70,0.45);
  animation: targetMarkPulse 0.65s ease-in-out infinite alternate;
  pointer-events: none;
}

.selected-unit img {
  animation:
    selectedReadyBob 0.72s ease-in-out infinite alternate,
    selectedReadyGlow 1.05s ease-in-out infinite alternate;
}

.acted-unit img {
  filter:
    grayscale(0.42)
    brightness(0.80)
    drop-shadow(0 2px 2px rgba(0,0,0,0.75)) !important;
}

@keyframes attackMotionPulse {
  0% {
    opacity: 0;
    transform: scale(0.56);
  }
  38% {
    opacity: 1;
    transform: scale(1.05);
  }
  100% {
    opacity: 0;
    transform: scale(1.34);
  }
}

@keyframes attackMotionSwipe {
  0% {
    opacity: 0;
    transform: rotate(-18deg) scaleX(0);
  }
  28% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    transform: rotate(-18deg) scaleX(1.28);
  }
}

@keyframes castCircle {
  0% {
    opacity: 0;
    transform: scale(0.55) rotate(0deg);
  }
  42% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    transform: scale(1.28) rotate(100deg);
  }
}

@keyframes castBeam {
  0% {
    opacity: 0;
    transform: scaleY(0.35) rotate(0deg);
  }
  35% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    transform: scaleY(1.1) rotate(60deg);
  }
}

@keyframes impactRing {
  0% {
    opacity: 0;
    transform: scale(0.42);
  }
  35% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    transform: scale(1.46);
  }
}

@keyframes impactSpark {
  0% {
    opacity: 0;
    transform: rotate(18deg) scaleX(0);
  }
  30% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    transform: rotate(18deg) scaleX(1.35);
  }
}

@keyframes evadeRing {
  0% {
    opacity: 0;
    transform: scale(0.55) translateY(0);
  }
  40% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    transform: scale(1.20) translateY(-8px);
  }
}

@keyframes targetMarkPulse {
  from {
    opacity: 0.72;
    transform: translateX(-50%) translateY(0);
  }
  to {
    opacity: 1;
    transform: translateX(-50%) translateY(-3px);
  }
}

@keyframes selectedReadyBob {
  from {
    transform: translateY(0) scale(1.04);
  }
  to {
    transform: translateY(-3px) scale(1.08);
  }
}

@keyframes selectedReadyGlow {
  from {
    filter:
      drop-shadow(0 2px 2px rgba(0,0,0,0.75))
      drop-shadow(0 0 6px rgba(80,150,255,0.35));
  }
  to {
    filter:
      drop-shadow(0 2px 2px rgba(0,0,0,0.75))
      drop-shadow(0 0 12px rgba(80,150,255,0.72));
  }
}

@media (max-width: 430px) {
  .attack-target-mark {
    font-size: 7px;
    top: -8px;
    padding: 1px 5px;
  }
}


/* v1.50.8 피격 / KO / 회복 모션 보강 */
.hit-flash-unit img {
  animation:
    unitHitFlash 0.34s ease-out,
    unitHitKnock 0.34s ease-out !important;
}

.effect-ko-burst {
  inset: -28% !important;
  z-index: 18 !important;
}

.effect-ko-burst::before {
  content: "";
  position: absolute;
  inset: 6%;
  border-radius: 999px;
  background:
    radial-gradient(circle, rgba(255,255,255,0.95) 0 8%, rgba(255,70,70,0.70) 14%, rgba(255,210,80,0.28) 38%, transparent 68%);
  box-shadow:
    0 0 22px rgba(255,80,80,0.72),
    0 0 38px rgba(255,210,80,0.38);
  animation: koBurstPop 0.78s ease-out forwards;
}

.effect-ko-burst::after {
  content: "KO";
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  color: #fff4c8;
  font-size: 18px;
  font-weight: 1000;
  text-shadow:
    0 0 8px rgba(255,60,60,0.95),
    0 2px 0 rgba(60,0,0,0.85);
  animation: koTextPop 0.82s ease-out forwards;
}

.effect-heal::before,
.effect-recover::before {
  content: "";
  position: absolute;
  inset: 10%;
  border-radius: 999px;
  background:
    radial-gradient(circle, rgba(160,255,190,0.54), rgba(70,255,140,0.18) 48%, transparent 70%);
  border: 1px solid rgba(120,255,180,0.34);
  box-shadow:
    0 0 18px rgba(120,255,180,0.45),
    inset 0 0 18px rgba(120,255,180,0.18);
  animation: healPulseRise 0.72s ease-out forwards;
}

.effect-heal::after,
.effect-recover::after {
  content: "+";
  position: absolute;
  left: 50%;
  top: 42%;
  transform: translate(-50%, -50%);
  color: #b8ffdd;
  font-size: 26px;
  font-weight: 1000;
  text-shadow:
    0 0 8px rgba(120,255,180,0.75),
    0 2px 0 rgba(0,40,20,0.75);
  animation: healCrossFloat 0.72s ease-out forwards;
}

.popup-crit {
  animation:
    popupFloat 0.78s ease-out forwards,
    popupCritShake 0.22s ease-in-out 2;
}

.popup-damage,
.popup-hazard {
  animation:
    popupFloat 0.78s ease-out forwards,
    popupHitBounce 0.22s ease-out;
}

@keyframes unitHitFlash {
  0% { filter: brightness(2.2) saturate(1.5) drop-shadow(0 0 10px rgba(255,255,255,0.95)); }
  55% { filter: brightness(1.3) saturate(1.2) drop-shadow(0 0 8px rgba(255,80,80,0.7)); }
  100% { filter: none; }
}

@keyframes unitHitKnock {
  0% { transform: translateX(0) scale(1.06); }
  28% { transform: translateX(-5px) scale(1.03); }
  56% { transform: translateX(4px) scale(1.02); }
  100% { transform: translateX(0) scale(1); }
}

@keyframes koBurstPop {
  0% { opacity: 0; transform: scale(0.42) rotate(0deg); }
  28% { opacity: 1; }
  100% { opacity: 0; transform: scale(1.65) rotate(35deg); }
}

@keyframes koTextPop {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(0.4); }
  30% { opacity: 1; transform: translate(-50%, -58%) scale(1.35); }
  100% { opacity: 0; transform: translate(-50%, -92%) scale(1); }
}

@keyframes healPulseRise {
  0% { opacity: 0; transform: scale(0.55) translateY(6px); }
  36% { opacity: 1; }
  100% { opacity: 0; transform: scale(1.35) translateY(-10px); }
}

@keyframes healCrossFloat {
  0% { opacity: 0; transform: translate(-50%, -35%) scale(0.55); }
  35% { opacity: 1; transform: translate(-50%, -50%) scale(1.1); }
  100% { opacity: 0; transform: translate(-50%, -92%) scale(0.9); }
}

@keyframes popupCritShake {
  0%, 100% { transform: translateX(0); }
  35% { transform: translateX(-3px); }
  70% { transform: translateX(3px); }
}

@keyframes popupHitBounce {
  0% { transform: translateY(0) scale(0.82); }
  60% { transform: translateY(-8px) scale(1.12); }
  100% { transform: translateY(-4px) scale(1); }
}


/* v1.50.9 스킬별 고유 이펙트 / 턴 연출 마무리 */
.effect-skill-fire-cast,
.effect-skill-ice-cast,
.effect-skill-shadow-cast,
.effect-skill-arrow-cast,
.effect-skill-heal-cast,
.effect-skill-guard-cast,
.effect-skill-aura {
  inset: -18% !important;
  z-index: 14 !important;
}

.effect-skill-fire-cast::before {
  content: "";
  position: absolute;
  inset: 12%;
  border-radius: 999px;
  background: conic-gradient(from 0deg, transparent, rgba(255,80,20,0.85), rgba(255,210,80,0.55), transparent);
  filter: blur(0.3px);
