    linear-gradient(45deg, transparent 0 34%, rgba(170,230,255,0.90) 48%, transparent 62%),
    linear-gradient(-45deg, transparent 0 34%, rgba(220,255,255,0.76) 48%, transparent 62%);
  box-shadow: 0 0 18px rgba(120,220,255,0.55);
  animation: iceCrystalFx 0.72s ease-out forwards;
