  position: absolute;
  inset: 5%;
  border-radius: 999px;
  background: radial-gradient(circle, rgba(190,80,255,0.58), rgba(30,0,60,0.55) 46%, transparent 72%);
  box-shadow: inset 0 0 22px rgba(0,0,0,0.88), 0 0 20px rgba(190,80,255,0.46);
  animation: shadowPulseFx 0.72s ease-out forwards;
}

.effect-skill-shadow-cast::after {
  content: "";
  position: absolute;
  left: 15%;
  top: 50%;
  width: 70%;
  height: 10px;
  border-radius: 999px;
  background: linear-gradient(to right, transparent, rgba(220,150,255,0.95), rgba(60,0,100,0.85), transparent);
  transform: rotate(-28deg) scaleX(0);
  animation: shadowSlashFx 0.66s ease-out forwards;
}

.effect-skill-arrow-cast::before {
  content: "";
  position: absolute;
  left: -5%;
  top: 44%;
  width: 110%;
  height: 8px;
  border-radius: 999px;
  background: linear-gradient(to right, transparent 0 12%, rgba(180,230,255,0.95) 36%, #fff 48%, rgba(245,210,140,0.80) 58%, transparent 86%);
  box-shadow: 0 0 14px rgba(180,230,255,0.62);
  transform: scaleX(0);
  transform-origin: left center;
  animation: arrowShotFx 0.48s ease-out forwards;
}

.effect-skill-arrow-cast::after {
  content: "➤";
  position: absolute;
  right: 8%;
  top: 31%;
  color: #fff;
  font-size: 22px;
  text-shadow: 0 0 8px rgba(180,230,255,0.8);
  opacity: 0;
  animation: arrowHeadFx 0.48s ease-out forwards;
}

.effect-skill-heal-cast::before {
  content: "";
  position: absolute;
  inset: 8%;
  border-radius: 999px;
  background: radial-gradient(circle, rgba(170,255,200,0.64), rgba(80,255,150,0.20) 50%, transparent 72%);
  border: 2px solid rgba(120,255,180,0.32);
  box-shadow: 0 0 22px rgba(120,255,180,0.48), inset 0 0 18px rgba(120,255,180,0.22);
  animation: healCastAura 0.76s ease-out forwards;
}

.effect-skill-heal-cast::after {
  content: "✚";
  position: absolute;
  left: 50%;
  top: 50%;
  color: #b8ffdd;
  font-size: 26px;
  font-weight: 900;
  transform: translate(-50%, -50%);
  text-shadow: 0 0 10px rgba(120,255,180,0.85);
  animation: healCastCross 0.76s ease-out forwards;
}

.effect-skill-guard-cast::before {
  content: "";
  position: absolute;
  inset: 4%;
  border-radius: 16px;
  border: 3px solid rgba(245,210,140,0.42);
  background: linear-gradient(135deg, rgba(245,210,140,0.20), rgba(255,255,255,0.06), rgba(245,210,140,0.10));
  box-shadow: 0 0 18px rgba(245,210,140,0.42), inset 0 0 22px rgba(245,210,140,0.15);
  animation: guardShieldFx 0.72s ease-out forwards;
}

.effect-skill-guard-cast::after {
  content: "盾";
  position: absolute;
  left: 50%;
  top: 50%;
  color: #f5d28c;
  font-size: 22px;
  font-weight: 900;
  transform: translate(-50%, -50%);
  text-shadow: 0 0 8px rgba(245,210,140,0.8);
  animation: guardTextFx 0.72s ease-out forwards;
}

.effect-skill-aura::before {
  content: "";
  position: absolute;
  inset: 12%;
  border-radius: 999px;
  background: radial-gradient(circle, rgba(255,255,255,0.45), rgba(245,210,140,0.18) 50%, transparent 72%);
  border: 1px solid rgba(245,210,140,0.30);
  animation: skillAuraFx 0.68s ease-out forwards;
}

.effect-crit-burst {
  inset: -35% !important;
  z-index: 20 !important;
}

.effect-crit-burst::before {
  content: "CRITICAL";
  position: absolute;
  left: 50%;
  top: 42%;
  transform: translate(-50%, -50%);
  color: #fff;
  font-size: 15px;
  font-weight: 1000;
  letter-spacing: 1px;
  text-shadow: 0 0 10px rgba(255,60,60,0.95), 0 2px 0 rgba(80,0,0,0.95);
  animation: criticalTextFx 0.74s ease-out forwards;
}

.effect-crit-burst::after {
  content: "";
  position: absolute;
  inset: 10%;
  border-radius: 999px;
  background: radial-gradient(circle, rgba(255,255,255,0.88), rgba(255,60,60,0.46) 32%, rgba(255,210,80,0.20) 54%, transparent 72%);
  animation: criticalBurstFx 0.74s ease-out forwards;
}

.effect-boss-hit-burst {
  inset: -30% !important;
  z-index: 19 !important;
}

.effect-boss-hit-burst::before {
  content: "";
  position: absolute;
  inset: 6%;
  border-radius: 999px;
  border: 2px solid rgba(255,210,80,0.55);
  box-shadow: 0 0 24px rgba(255,60,60,0.55), inset 0 0 22px rgba(255,210,80,0.25);
  animation: bossHitRoar 0.72s ease-out forwards;
}

@keyframes skillSpinBurst { 0%{opacity:0;transform:scale(.45) rotate(0)} 35%{opacity:1} 100%{opacity:0;transform:scale(1.32) rotate(180deg)} }
@keyframes skillBeamDrop { 0%{opacity:0;transform:scaleY(.35) rotate(0)} 35%{opacity:1} 100%{opacity:0;transform:scaleY(1.2) rotate(55deg)} }
