  0% { opacity: 0; transform: scale(0.38); }
  42% { opacity: 1; }
  100% { opacity: 0; transform: scale(1.52); }
}

@keyframes combatHealRise {
  0% { opacity: 0; transform: translate(-50%, -18%) scale(0.5); }
  36% { opacity: 1; transform: translate(-50%, -50%) scale(1.12); }
  100% { opacity: 0; transform: translate(-50%, -112%) scale(0.94); }
}

@keyframes combatGuardGuard {
  0% { opacity: 0; transform: scale(0.55); }
  36% { opacity: 1; }
  100% { opacity: 0; transform: scale(1.28); }
}

@keyframes combatAuraImpact {
