  36% { opacity: 1; }
  100% { opacity: 0; transform: scale(1.18) translateY(-10px); }
}

@keyframes combatEvadeSlip {
  0% { opacity: 0; transform: translateX(-10px) skewX(-14deg); }
  32% { opacity: 1; }
  100% { opacity: 0; transform: translateX(18px) skewX(-14deg); }
}

