/* v1.99.6 battlefield free unit motion */
.classic-pixel-map .free-motion-unit img {
  animation: classicFreeUnitIdle 1.28s ease-in-out infinite var(--unit-idle-delay, 0ms) !important;
  transform-origin: 50% 92% !important;
  will-change: translate, rotate, scale, filter;
}

.classic-pixel-map .free-motion-unit.ally-unit:not(.selected-unit):not(.acted-unit):not(.wounded-motion-unit) img {
  animation-name: classicFreeAllyIdle !important;
}

.classic-pixel-map .free-motion-unit.enemy-unit:not(.acted-unit):not(.wounded-motion-unit) img {
  animation-name: classicFreeEnemyIdle !important;
  animation-duration: 1.46s !important;
}

.classic-pixel-map .free-motion-unit.boss-unit:not(.acted-unit) img,
.classic-pixel-map .free-motion-unit.phase2-unit:not(.acted-unit) img {
  animation-name: classicFreeBossIdle !important;
  animation-duration: 1.62s !important;
}

.classic-pixel-map .ready-motion-unit:not(.selected-unit):not(.acted-unit):not(.action-motion) img {
  animation: classicReadyUnitMotion 0.86s ease-in-out infinite var(--unit-idle-delay, 0ms) !important;
}

.classic-pixel-map .selected-unit:not(.action-motion) img {
  animation: classicSelectedFreeMotion 0.72s ease-in-out infinite var(--unit-idle-delay, 0ms) !important;
}

.classic-pixel-map .wounded-motion-unit:not(.action-motion) img {
  animation: classicWoundedUnitMotion 1.08s ease-in-out infinite var(--unit-idle-delay, 0ms) !important;
}

.classic-pixel-map .acted-unit.free-motion-unit:not(.selected-unit) img {
  animation: classicTiredUnitMotion 1.78s ease-in-out infinite var(--unit-idle-delay, 0ms) !important;
}

.classic-pixel-map .free-motion-unit::before {
  animation: classicFreeUnitShadow 1.28s ease-in-out infinite var(--unit-idle-delay, 0ms) !important;
  transform-origin: 50% 50%;
}

.classic-pixel-map .selected-unit::before,
.classic-pixel-map .ready-motion-unit::before {
  animation-duration: 0.82s !important;
}

.classic-pixel-map .hit-flash-unit img {
  animation: classicBodyHitRecoil 0.5s ease-out both !important;
}

.classic-pixel-map .map-moving-unit img {
  animation: classicFreeWalkCycle 0.24s ease-in-out infinite !important;
  transform-origin: 50% 92% !important;
  will-change: translate, rotate, scale;
}

.classic-pixel-map .map-moving-unit.moving-left img {
  transform: translateY(-22%) scaleX(-1) !important;
}

.classic-pixel-map .map-moving-unit.moving-up img {
  animation-name: classicFreeWalkUp !important;
}

.classic-pixel-map .map-moving-unit.moving-down img {
  animation-name: classicFreeWalkDown !important;
}

.classic-pixel-map .map-moving-unit.boss-moving img {
  animation: classicFreeBossWalkCycle 0.28s ease-in-out infinite !important;
}

.classic-pixel-map .action-motion img {
  will-change: translate, rotate, scale;
}

@keyframes classicFreeUnitIdle {
  0%, 100% {
    translate: 0 var(--unit-idle-down, 0px);
    rotate: 0deg;
    scale: 1;
  }
  28% {
    translate: var(--unit-idle-side, 0px) var(--unit-idle-up, -3px);
    rotate: var(--unit-idle-tilt, 2deg);
    scale: 1.018;
  }
  58% {
    translate: var(--unit-idle-side-away, 0px) 0;
    rotate: var(--unit-idle-tilt-soft, -1deg);
    scale: 0.998;
  }
}

@keyframes classicFreeAllyIdle {
  0%, 100% {
    translate: 0 0;
    rotate: -0.5deg;
    scale: 1;
  }
  34% {
    translate: var(--unit-idle-side, 0px) var(--unit-idle-up, -3px);
    rotate: var(--unit-idle-tilt, 2deg);
    scale: 1.025;
  }
  68% {
    translate: 0 1px;
    rotate: -1deg;
    scale: 1.005;
  }
}

@keyframes classicFreeEnemyIdle {
  0%, 100% {
    translate: 0 0;
    rotate: 0deg;
    scale: 1;
  }
  30% {
    translate: var(--unit-idle-side-away, 0px) -2px;
    rotate: var(--unit-idle-tilt-away, -2deg);
    scale: 1.018;
  }
  62% {
    translate: var(--unit-idle-side, 0px) 1px;
    rotate: var(--unit-idle-tilt, 2deg);
    scale: 0.998;
  }
}

@keyframes classicFreeBossIdle {
  0%, 100% {
    translate: 0 0;
    rotate: -0.5deg;
    scale: 1;
    filter:
      drop-shadow(0 0 1px #050302)
      drop-shadow(0 3px 2px rgba(0,0,0,0.74))
      drop-shadow(0 0 9px rgba(255,70,60,0.20));
  }
  45% {
    translate: 0 -4px;
    rotate: 0.8deg;
    scale: 1.025;
    filter:
      drop-shadow(0 0 1px #050302)
      drop-shadow(0 4px 3px rgba(0,0,0,0.78))
      drop-shadow(0 0 14px rgba(255,70,60,0.34));
  }
}

@keyframes classicReadyUnitMotion {
  0%, 100% {
    translate: 0 0;
    rotate: -1deg;
    scale: 1;
  }
  42% {
    translate: var(--unit-idle-side, 0px) -5px;
    rotate: var(--unit-idle-tilt, 2deg);
    scale: 1.04;
  }
  72% {
    translate: var(--unit-idle-side-away, 0px) -1px;
    rotate: -1deg;
    scale: 1.015;
  }
}

@keyframes classicSelectedFreeMotion {
  0%, 100% {
    translate: 0 0;
    rotate: -2deg;
    scale: 1.02;
  }
  45% {
    translate: var(--unit-idle-side, 0px) -6px;
    rotate: var(--unit-idle-tilt, 2deg);
    scale: 1.07;
  }
  76% {
    translate: var(--unit-idle-side-away, 0px) -2px;
    rotate: 2deg;
    scale: 1.035;
  }
}

@keyframes classicWoundedUnitMotion {
  0%, 100% {
    translate: 0 1px;
    rotate: -3deg;
    scale: 0.985;
  }
  50% {
    translate: var(--unit-idle-side, 0px) -2px;
    rotate: 2deg;
    scale: 1;
  }
}

@keyframes classicTiredUnitMotion {
  0%, 100% {
    translate: 0 1px;
    rotate: -1deg;
    scale: 0.985;
  }
  50% {
    translate: 0 -1px;
    rotate: 1deg;
    scale: 0.995;
  }
}

@keyframes classicFreeUnitShadow {
  0%, 100% {
    scale: 0.88 0.82;
    opacity: 0.68;
  }
  45% {
    scale: 1.08 0.92;
    opacity: 0.46;
  }
}

@keyframes classicBodyHitRecoil {
  0% {
    translate: 0 0;
    rotate: 0deg;
    scale: 1;
    filter:
      brightness(1.65)
      drop-shadow(0 0 1px #050302)
      drop-shadow(0 0 9px rgba(255,230,180,0.82));
  }
  22% {
    translate: -7px -3px;
    rotate: -8deg;
    scale: 1.05;
  }
  44% {
    translate: 6px 1px;
    rotate: 6deg;
    scale: 0.98;
  }
  68% {
    translate: -3px 0;
    rotate: -3deg;
    scale: 1.01;
  }
  100% {
    translate: 0 0;
    rotate: 0deg;
    scale: 1;
  }
}

@keyframes classicFreeWalkCycle {
  0%, 100% {
    translate: -1px 0;
    rotate: -4deg;
    scale: 1;
  }
  50% {
    translate: 2px -8px;
    rotate: 4deg;
    scale: 1.055;
  }
}

@keyframes classicFreeWalkUp {
  0%, 100% {
    translate: 0 1px;
    rotate: -3deg;
    scale: 0.99;
  }
  50% {
    translate: 0 -7px;
    rotate: 3deg;
    scale: 1.04;
  }
}

@keyframes classicFreeWalkDown {
  0%, 100% {
    translate: 0 0;
    rotate: -4deg;
    scale: 1.01;
  }
  50% {
    translate: 0 -9px;
    rotate: 4deg;
    scale: 1.065;
  }
}

@keyframes classicFreeBossWalkCycle {
  0%, 100% {
    translate: -1px 0;
    rotate: -2deg;
    scale: 1.01;
  }
  50% {
    translate: 2px -7px;
    rotate: 2deg;
    scale: 1.045;
  }
}

@media (prefers-reduced-motion: reduce) {
  .classic-pixel-map .free-motion-unit img,
  .classic-pixel-map .free-motion-unit::before,
  .classic-pixel-map .map-moving-unit img {
    animation-duration: 2.4s !important;
  }
}

