@keyframes dkV1997VsBreath {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(0.76); }
  18% { opacity: 0.9; transform: translate(-50%, -50%) scale(1.04); }
  52% { opacity: 0.74; transform: translate(-50%, -50%) scale(0.98); }
  78% { opacity: 0.86; transform: translate(-50%, -50%) scale(1.02); }
  100% { opacity: 0.58; transform: translate(-50%, -50%) scale(0.96); }
}

@keyframes dkV1997FinishMark {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(0.72); }
  18% { opacity: 1; transform: translate(-50%, -50%) scale(1.08); }
  54% { opacity: 0.9; transform: translate(-50%, -50%) scale(1.02); }
  78% { opacity: 0.5; transform: translate(-50%, -50%) scale(1.18); }
  100% { opacity: 0.22; transform: translate(-50%, -50%) scale(1.28); }
}

@keyframes dkV1997AttackerStage {
  0% { transform: translateX(-12px); opacity: 0.96; }
  22% { transform: translateX(-24px); }
  46% { transform: translateX(38px); }
  56% { transform: translateX(62px); }
  72% { transform: translateX(16px); }
  100% { transform: translateX(0); opacity: 1; }
}

@keyframes dkV1997DefenderStage {
  0%, 50% { transform: translateX(0); }
  58% { transform: translateX(12px); }
  68% { transform: translateX(-5px); }
  82%, 100% { transform: translateX(0); }
}

@keyframes dkV1997AttackerBody {
  0% { transform: translateY(0) rotate(0deg) scale(1); filter: brightness(0.98); }
  22% { transform: translateY(3px) rotate(-2deg) scaleX(0.98) scaleY(1.02); }
  42% { transform: translateY(-6px) rotate(3deg) scaleX(1.04) scaleY(0.98); filter: brightness(1.16); }
  54% { transform: translateY(-4px) rotate(-5deg) scaleX(0.97) scaleY(1.05); filter: brightness(1.38); }
  68% { transform: translateY(0) rotate(2deg) scale(1.01); filter: brightness(1.12); }
  100% { transform: translateY(0) rotate(0deg) scale(1); filter: brightness(1); }
}

@keyframes dkV1997DefenderBody {
  0%, 50% { transform: scaleX(-1) translateY(0) rotate(0deg) scale(1); filter: brightness(1); }
  58% { transform: scaleX(-1) translateX(10px) translateY(-3px) rotate(-4deg) scaleX(1.04) scaleY(0.96); filter: brightness(1.45); }
  68% { transform: scaleX(-1) translateX(-4px) translateY(1px) rotate(2deg) scaleX(0.98) scaleY(1.02); filter: brightness(1.12); }
  100% { transform: scaleX(-1) translateX(0) translateY(0) rotate(0deg) scale(1); filter: brightness(1); }
}

@keyframes dkV1997PlatformWeight {
  0%, 32% { transform: scaleX(0.94); opacity: 0.62; }
  54% { transform: scaleX(1.14); opacity: 0.82; }
  72%, 100% { transform: scaleX(1); opacity: 0.68; }
}

@keyframes dkV1997DamageText {
  0% { opacity: 0; transform: translate(-50%, -38%) scale(0.64); }
  44% { opacity: 1; transform: translate(-50%, -64%) scale(1.12); }
  100% { opacity: 1; transform: translate(-50%, -52%) scale(1); }
}

@keyframes dkV1997Slash {
  0% { opacity: 0; transform: translateX(-42px) rotate(-18deg) scaleX(0.18); }
  38% { opacity: 0.95; transform: translateX(10px) rotate(-18deg) scaleX(1.02); }
  100% { opacity: 0; transform: translateX(76px) rotate(-12deg) scaleX(0.62); }
}

@keyframes dkV1997Spark {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(0.3); }
  42% { opacity: 0.82; transform: translate(-50%, -50%) scale(1); }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(1.34); }
}

@keyframes dkV1997Weapon {
  0%, 32% { opacity: 0; transform: rotate(-42deg) translateX(-18px) translateY(8px) scaleX(0.1); }
  48% { opacity: 0.9; transform: rotate(-28deg) translateX(16px) translateY(-6px) scaleX(0.82); }
  58% { opacity: 0.95; transform: rotate(-16deg) translateX(72px) translateY(-12px) scaleX(1.05); }
  100% { opacity: 0; transform: rotate(-6deg) translateX(112px) translateY(-2px) scaleX(0.44); }
}

@keyframes dkV1997Trail {
  0%, 38% { opacity: 0; transform: rotate(-32deg) translateX(-22px) scale(0.4); }
  56% { opacity: 0.62; transform: rotate(-18deg) translateX(42px) scale(0.92); }
  100% { opacity: 0; transform: rotate(-8deg) translateX(98px) scale(1.04); }
}

@keyframes dkV1997CasterStage {
  0% { transform: translateX(-8px); }
  34% { transform: translateX(0); }
  56% { transform: translateX(8px); }
  100% { transform: translateX(0); }
}

@keyframes dkV1997ArcherBody {
  0% { transform: translateY(0) rotate(0deg) scale(1); filter: brightness(0.98); }
  28% { transform: translateY(2px) rotate(-3deg) scaleX(0.98) scaleY(1.02); }
  48% { transform: translateY(-6px) rotate(4deg) scaleX(1.04) scaleY(0.98); filter: brightness(1.24); }
  62% { transform: translateY(-2px) rotate(-1deg) scaleX(0.98) scaleY(1.02); filter: brightness(1.34); }
  100% { transform: translateY(0) rotate(0deg) scale(1); filter: brightness(1); }
}

@keyframes dkV1997CasterBody {
  0% { transform: translateY(0) rotate(0deg) scale(1); filter: brightness(0.98); }
  32% { transform: translateY(-6px) rotate(-2deg) scale(1.03); filter: brightness(1.18); }
  54% { transform: translateY(-10px) rotate(3deg) scale(1.05); filter: brightness(1.38) saturate(1.12); }
  76% { transform: translateY(-3px) rotate(-1deg) scale(1.02); }
  100% { transform: translateY(0) rotate(0deg) scale(1); filter: brightness(1); }
}

@keyframes dkV1997DefenderRangedHit {
  0%, 50% { transform: scaleX(-1) translateY(0) rotate(0deg); filter: brightness(1); }
  60% { transform: scaleX(-1) translateX(14px) translateY(-6px) rotate(-4deg) scale(1.04); filter: brightness(1.48); }
  76% { transform: scaleX(-1) translateX(-4px) translateY(1px) rotate(2deg); }
  100% { transform: scaleX(-1) translateX(0) translateY(0) rotate(0deg); filter: brightness(1); }
}

@keyframes dkV1997HealedBody {
  0%, 42% { transform: scaleX(-1) translateY(0) scale(1); filter: brightness(1); }
  58% { transform: scaleX(-1) translateY(-9px) scale(1.04); filter: brightness(1.42) saturate(1.18); }
  82% { transform: scaleX(-1) translateY(-2px) scale(1.01); }
  100% { transform: scaleX(-1) translateY(0) scale(1); filter: brightness(1); }
}

@keyframes dkV1997MissStage {
  0% { transform: translateX(-10px); }
  44% { transform: translateX(52px); }
  66% { transform: translateX(70px); }
  100% { transform: translateX(0); }
}

@keyframes dkV1997MissBody {
  0% { transform: rotate(0deg) scale(1); }
  42% { transform: translateY(-5px) rotate(4deg) scale(1.04); filter: brightness(1.18); }
  62% { transform: translateY(-3px) rotate(-5deg) scale(0.98); filter: brightness(1.24); }
  100% { transform: translateY(0) rotate(0deg) scale(1); filter: brightness(1); }
}

@keyframes dkV1997EvadeBody {
  0%, 42% { transform: scaleX(-1) translateX(0) translateY(0); opacity: 1; }
  56% { transform: scaleX(-1) translateX(22px) translateY(-7px) rotate(-3deg) scale(0.98); opacity: 0.72; filter: brightness(1.2); }
  76% { transform: scaleX(-1) translateX(-3px) translateY(0) rotate(1deg); opacity: 1; }
  100% { transform: scaleX(-1) translateX(0) translateY(0) rotate(0deg); opacity: 1; filter: brightness(1); }
}

@keyframes dkV1997FinishAttackerBody {
  0% { transform: translateY(0) rotate(0deg) scale(1); filter: brightness(0.98); }
  22% { transform: translateY(3px) rotate(-3deg) scaleX(0.98) scaleY(1.03); }
  42% { transform: translateY(-8px) rotate(4deg) scaleX(1.06) scaleY(0.96); filter: brightness(1.28); }
  56% { transform: translateY(-7px) rotate(-7deg) scaleX(0.96) scaleY(1.08); filter: brightness(1.72); }
  76% { transform: translateY(0) rotate(3deg) scale(1.03); filter: brightness(1.24); }
  100% { transform: translateY(0) rotate(0deg) scale(1); filter: brightness(1); }
}

@keyframes dkV1997FinishDefenderBody {
  0%, 48% { transform: scaleX(-1) translateY(0) rotate(0deg) scale(1); filter: brightness(1); opacity: 1; }
  58% { transform: scaleX(-1) translateX(18px) translateY(-8px) rotate(-7deg) scaleX(1.06) scaleY(0.94); filter: brightness(1.75); }
  72% { transform: scaleX(-1) translateX(-7px) translateY(3px) rotate(4deg) scaleX(0.96) scaleY(1.06); opacity: 0.86; }
  100% { transform: scaleX(-1) translateX(0) translateY(0) rotate(0deg) scale(1); filter: brightness(1); opacity: 1; }
}

