@keyframes dkV1998AttackerStage {
  0%, 18% { transform: translateX(0); opacity: 1; }
  30% { transform: translateX(-8px); }
  44% { transform: translateX(24px); }
  54% { transform: translateX(38px); }
  66% { transform: translateX(10px); }
  100% { transform: translateX(0); opacity: 1; }
}

@keyframes dkV1998DefenderStage {
  0%, 50% { transform: translateX(0); }
  58% { transform: translateX(8px); }
  70% { transform: translateX(-4px); }
  84%, 100% { transform: translateX(0); }
}

@keyframes dkV1998AttackerBody {
  0%, 18% { transform: translateY(0) rotate(0deg) scale(1); filter: brightness(1); }
  30% { transform: translateY(2px) rotate(-2deg) scaleX(0.98) scaleY(1.02); }
  44% { transform: translateY(-4px) rotate(2deg) scaleX(1.03) scaleY(0.98); filter: brightness(1.12); }
  54% { transform: translateY(-2px) rotate(-3deg) scaleX(0.98) scaleY(1.03); filter: brightness(1.32); }
  70% { transform: translateY(0) rotate(1deg) scale(1); filter: brightness(1.08); }
  100% { transform: translateY(0) rotate(0deg) scale(1); filter: brightness(1); }
}

@keyframes dkV1998DefenderBody {
  0%, 50% { transform: scaleX(-1) translateX(0) translateY(0) rotate(0deg) scale(1); filter: brightness(1); }
  58% { transform: scaleX(-1) translateX(7px) translateY(-2px) rotate(-3deg) scaleX(1.03) scaleY(0.98); filter: brightness(1.35); }
  70% { transform: scaleX(-1) translateX(-3px) translateY(1px) rotate(2deg) scaleX(0.99) scaleY(1.01); filter: brightness(1.08); }
  100% { transform: scaleX(-1) translateX(0) translateY(0) rotate(0deg) scale(1); filter: brightness(1); }
}

@keyframes dkV1998Platform {
  0%, 34% { transform: scaleX(0.9); opacity: 0.5; }
  54% { transform: scaleX(1.06); opacity: 0.68; }
  100% { transform: scaleX(0.94); opacity: 0.52; }
}

@keyframes dkV1998Weapon {
  0%, 40% { opacity: 0; transform: rotate(-26deg) translateX(-12px) scaleX(0.1); }
  50% { opacity: 0.82; transform: rotate(-20deg) translateX(28px) scaleX(0.82); }
  64% { opacity: 0.35; transform: rotate(-12deg) translateX(68px) scaleX(0.58); }
  100% { opacity: 0; transform: rotate(-12deg) translateX(88px) scaleX(0.2); }
}

@keyframes dkV1998Trail {
  0%, 44% { opacity: 0; transform: rotate(-26deg) translateX(-14px) scale(0.4); }
  54% { opacity: 0.45; transform: rotate(-18deg) translateX(28px) scale(0.82); }
  100% { opacity: 0; transform: rotate(-12deg) translateX(72px) scale(0.95); }
}

@keyframes dkV1998Slash {
  0% { opacity: 0; transform: translateX(-24px) rotate(-14deg) scaleX(0.2); }
  42% { opacity: 0.9; transform: translateX(0) rotate(-14deg) scaleX(1); }
  100% { opacity: 0; transform: translateX(38px) rotate(-10deg) scaleX(0.62); }
}

@keyframes dkV1998Spark {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(0.34); }
  44% { opacity: 0.74; transform: translate(-50%, -50%) scale(0.95); }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(1.24); }
}

@keyframes dkV1998HitFlash {
  0%, 30% { opacity: 0; transform: translate(-50%, -50%) scale(0.56); }
  48% { opacity: 0.55; transform: translate(-50%, -50%) scale(0.98); }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(1.24); }
}

@keyframes dkV1998DamageText {
  0% { opacity: 0; transform: translate(-50%, -42%) scale(0.72); }
  40% { opacity: 1; transform: translate(-50%, -58%) scale(1.04); }
  100% { opacity: 1; transform: translate(-50%, -48%) scale(1); }
}

@keyframes dkV1998CasterStage {
  0%, 100% { transform: translateX(0); }
  42% { transform: translateX(6px); }
}

@keyframes dkV1998ArcherBody {
  0%, 26% { transform: translateY(0) rotate(0deg) scale(1); filter: brightness(1); }
  42% { transform: translateY(2px) rotate(-3deg) scaleX(0.98) scaleY(1.02); }
  56% { transform: translateY(-3px) rotate(3deg) scaleX(1.03) scaleY(0.98); filter: brightness(1.22); }
  100% { transform: translateY(0) rotate(0deg) scale(1); filter: brightness(1); }
}

@keyframes dkV1998CasterBody {
  0%, 22% { transform: translateY(0) rotate(0deg) scale(1); filter: brightness(1); }
  42% { transform: translateY(-5px) rotate(-1deg) scale(1.03); filter: brightness(1.14); }
  58% { transform: translateY(-7px) rotate(2deg) scale(1.04); filter: brightness(1.28); }
  100% { transform: translateY(0) rotate(0deg) scale(1); filter: brightness(1); }
}

@keyframes dkV1998DefenderRangedHit {
  0%, 48% { transform: scaleX(-1) translateX(0) translateY(0) rotate(0deg); filter: brightness(1); }
  60% { transform: scaleX(-1) translateX(9px) translateY(-4px) rotate(-3deg) scale(1.03); filter: brightness(1.35); }
  76% { transform: scaleX(-1) translateX(-3px) translateY(1px) rotate(1deg); }
  100% { transform: scaleX(-1) translateX(0) translateY(0) rotate(0deg); filter: brightness(1); }
}

@keyframes dkV1998HealedBody {
  0%, 44% { transform: scaleX(-1) translateY(0) scale(1); filter: brightness(1); }
  58% { transform: scaleX(-1) translateY(-6px) scale(1.03); filter: brightness(1.28) saturate(1.12); }
  100% { transform: scaleX(-1) translateY(0) scale(1); filter: brightness(1); }
}

@keyframes dkV1998MissStage {
  0%, 24% { transform: translateX(0); }
  44% { transform: translateX(32px); }
  64% { transform: translateX(46px); }
  100% { transform: translateX(0); }
}

@keyframes dkV1998MissBody {
  0%, 30% { transform: translateY(0) rotate(0deg) scale(1); }
  48% { transform: translateY(-4px) rotate(3deg) scale(1.03); filter: brightness(1.12); }
  66% { transform: translateY(-2px) rotate(-3deg) scale(0.99); }
  100% { transform: translateY(0) rotate(0deg) scale(1); filter: brightness(1); }
}

@keyframes dkV1998EvadeBody {
  0%, 40% { transform: scaleX(-1) translateX(0) translateY(0); opacity: 1; }
  56% { transform: scaleX(-1) translateX(18px) translateY(-5px) rotate(-2deg) scale(0.98); opacity: 0.72; filter: brightness(1.18); }
  74% { transform: scaleX(-1) translateX(-2px) translateY(0) rotate(1deg); opacity: 1; }
  100% { transform: scaleX(-1) translateX(0) translateY(0) rotate(0deg); opacity: 1; filter: brightness(1); }
}

@keyframes dkV1998FinishAttackerBody {
  0%, 20% { transform: translateY(0) rotate(0deg) scale(1); filter: brightness(1); }
  34% { transform: translateY(2px) rotate(-3deg) scaleX(0.98) scaleY(1.03); }
  50% { transform: translateY(-6px) rotate(3deg) scaleX(1.05) scaleY(0.96); filter: brightness(1.28); }
  60% { transform: translateY(-4px) rotate(-5deg) scaleX(0.97) scaleY(1.07); filter: brightness(1.58); }
  76% { transform: translateY(0) rotate(2deg) scale(1.02); }
  100% { transform: translateY(0) rotate(0deg) scale(1); filter: brightness(1); }
}

@keyframes dkV1998FinishDefenderBody {
  0%, 48% { transform: scaleX(-1) translateY(0) rotate(0deg) scale(1); filter: brightness(1); opacity: 1; }
  58% { transform: scaleX(-1) translateX(12px) translateY(-6px) rotate(-5deg) scaleX(1.04) scaleY(0.96); filter: brightness(1.55); }
  74% { transform: scaleX(-1) translateX(-5px) translateY(2px) rotate(3deg) scaleX(0.98) scaleY(1.04); opacity: 0.9; }
  100% { transform: scaleX(-1) translateX(0) translateY(0) rotate(0deg) scale(1); filter: brightness(1); opacity: 1; }
}

