/* v1.99.20 wider touch-pannable battlefield */
.battle-map-scroll-shell {
  width: 100%;
  max-width: 100%;
  overflow: auto !important;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  touch-action: pan-x pan-y;
  cursor: grab;
  scrollbar-gutter: stable both-edges;
}

.battle-map-scroll-shell.is-panning {
  cursor: grabbing;
  touch-action: none;
}

.battle-map.classic-pixel-map {
  --battle-tile-size: clamp(34px, 8.2vw, 42px);
  width: max-content !important;
  min-width: 100% !important;
  max-width: none !important;
  grid-auto-rows: var(--battle-tile-size) !important;
}

.battle-map.classic-pixel-map .tile,
.battle-map.classic-pixel-map .terrain-rich-tile {
  width: var(--battle-tile-size) !important;
  min-width: var(--battle-tile-size) !important;
  height: var(--battle-tile-size) !important;
  min-height: var(--battle-tile-size) !important;
  aspect-ratio: 1 / 1;
}

.battle-compact-mode .battle-map-scroll-shell {
  margin-top: 8px;
  max-height: min(62dvh, 620px) !important;
  overflow: auto !important;
}

.battle-compact-mode .battle-map.classic-pixel-map {
  padding: 0 !important;
  gap: 0 !important;
}

.native-capacitor-app .battle-map-scroll-shell {
  max-height: min(58dvh, 600px) !important;
  overflow: auto !important;
}

@media (max-width: 720px) {
  .battle-compact-mode .battle-map-scroll-shell {
    max-height: 56dvh !important;
  }

  .battle-map.classic-pixel-map {
    --battle-tile-size: clamp(34px, 9.2vw, 40px);
  }
}

@media (max-width: 380px) {
  .battle-map.classic-pixel-map {
    --battle-tile-size: 34px;
  }
}

