@keyframes dkV19950SpeedSweep {
  0%, 34%, 72%, 100% { opacity: 0; transform: skewY(-9deg) translateX(-24%); }
  42% { opacity: 0.16; transform: skewY(-9deg) translateX(-8%); }
  50%, 56% { opacity: 0.34; transform: skewY(-9deg) translateX(16%); }
  64% { opacity: 0.08; transform: skewY(-9deg) translateX(38%); }
}

@keyframes dkV19950MeleeAttackerRoot {
  0%, 16% { transform: translateX(-20px); filter: brightness(1); }
  28% { transform: translateX(-35px); filter: brightness(0.96); }
  42% { transform: translateX(58px); filter: brightness(1.18); }
  48%, 56% { transform: translateX(92px); filter: brightness(1.32); }
  68% { transform: translateX(52px); filter: brightness(1.06); }
  84%, 100% { transform: translateX(0); filter: brightness(1); }
}

@keyframes dkV19950MeleeAttackerRig {
  0%, 16% { transform: translateY(0) rotate(0deg) scale(1); }
  28% { transform: translate(-8px, 9px) rotate(-7deg) scaleX(0.95) scaleY(1.06); }
  40% { transform: translate(8px, -5px) rotate(6deg) scaleX(1.08) scaleY(0.94); }
  48%, 56% { transform: translate(13px, -2px) rotate(-9deg) scaleX(1.13) scaleY(0.90); }
  68% { transform: translate(2px, 2px) rotate(3deg) scaleX(0.98) scaleY(1.02); }
  84%, 100% { transform: translateY(0) rotate(0deg) scale(1); }
}

@keyframes dkV19950MeleeAttackerBody {
  0%, 22%, 100% { transform: translateY(0) rotate(0deg); filter: brightness(1) saturate(1); }
  30% { transform: translateY(3px) rotate(-3deg); filter: brightness(0.96) saturate(1); }
  44% { transform: translateY(-5px) rotate(4deg); filter: brightness(1.20) saturate(1.08); }
  50%, 56% { transform: translateY(-2px) rotate(-5deg); filter: brightness(1.36) saturate(1.12); }
  70% { transform: translateY(2px) rotate(2deg); filter: brightness(1.05) saturate(1.02); }
}

@keyframes dkV19950MeleeDefenderRoot {
  0%, 48% { transform: translateX(0); filter: brightness(1); }
  52%, 58% { transform: translateX(25px); filter: brightness(1.24); }
  68% { transform: translateX(-8px); filter: brightness(1.02); }
  82%, 100% { transform: translateX(0); filter: brightness(1); }
}

@keyframes dkV19950MeleeDefenderRig {
  0%, 48% { transform: scaleX(-1) translateX(0) translateY(0) rotate(0deg) scale(1); }
  52%, 58% { transform: scaleX(-1) translateX(16px) translateY(-7px) rotate(-8deg) scaleX(1.10) scaleY(0.88); }
  68% { transform: scaleX(-1) translateX(-6px) translateY(4px) rotate(4deg) scaleX(0.96) scaleY(1.05); }
  82%, 100% { transform: scaleX(-1) translateX(0) translateY(0) rotate(0deg) scale(1); }
}

@keyframes dkV19950MeleeDefenderBody {
  0%, 48%, 100% { transform: translateY(0); filter: brightness(1) saturate(1); }
  52%, 58% { transform: translateY(-2px); filter: brightness(1.62) saturate(1.16); }
  68% { transform: translateY(2px); filter: brightness(0.98) saturate(0.96); }
}

