@keyframes vsDuelSpeedSweep {
  0% { transform: translateX(-22%) skewY(-5deg); }
  100% { transform: translateX(22%) skewY(-5deg); }
}

@keyframes vsDuelCenterFlare {
  0%, 100% { opacity: 0.40; transform: rotate(16deg) scaleY(0.82); }
  48%, 58% { opacity: 0.98; transform: rotate(16deg) scaleY(1.12); }
}

@keyframes vsDuelPulse {
  0%, 100% { opacity: 0.30; transform: translate(-50%, -50%) scale(0.82); }
  48%, 58% { opacity: 0.78; transform: translate(-50%, -50%) scale(1.12); }
}

@keyframes vsDuelAttackerPose {
  0%, 100% { transform: rotate(0deg) translate(0, 0) scale(1); filter: brightness(1); }
  38% { transform: rotate(-4deg) translate(-6px, 3px) scaleX(0.98) scaleY(1.03); }
  52%, 62% { transform: rotate(6deg) translate(8px, -5px) scaleX(1.06) scaleY(0.96); filter: brightness(1.22); }
}

@keyframes vsDuelDefenderPose {
  0%, 100% { transform: scaleX(-1) rotate(0deg) translate(0, 0) scale(1); filter: brightness(1); }
  44% { transform: scaleX(-1) rotate(3deg) translate(-5px, 1px) scale(1.02); }
  56%, 64% { transform: scaleX(-1) rotate(-5deg) translate(7px, -3px) scaleX(1.04) scaleY(0.98); filter: brightness(1.16); }
}

@keyframes vsDuelMarkClash {
  0%, 100% { transform: translate(-50%, -50%) scale(1); }
  48%, 58% { transform: translate(-50%, -50%) scale(1.12); }
}

@keyframes vsDuelClashSlash {
  0%, 36% { opacity: 0; transform: translateX(-80px) rotate(-11deg) scaleX(0.18); }
  50%, 62% { opacity: 1; transform: translateX(0) rotate(-11deg) scaleX(1); }
  82%, 100% { opacity: 0; transform: translateX(96px) rotate(-11deg) scaleX(0.48); }
}

@keyframes vsDuelImpactPop {
  0%, 48%, 64%, 100% { opacity: 0; transform: translate(-50%, -50%) scale(0.34); }
  52%, 60% { opacity: 1; transform: translate(-50%, -50%) scale(1.08); }
}

