/* v1.99.102 launch-grade VS cutscene and turn phase banner */
.turn-phase-banner {
  position: fixed;
  left: 50%;
  top: 42%;
  z-index: 190;
  width: min(360px, 86vw);
  min-height: 124px;
  display: grid;
  align-content: center;
  gap: 4px;
  transform: translate(-50%, -50%);
  padding: 18px 22px;
  border: 1px solid rgba(244, 194, 100, 0.72);
  border-radius: 0;
  color: #ffe9a7;
  text-align: center;
  pointer-events: none;
  background:
    linear-gradient(90deg, transparent, rgba(255, 230, 160, 0.18), transparent),
    radial-gradient(ellipse at 50% 30%, rgba(255, 229, 150, 0.18), transparent 56%),
    linear-gradient(180deg, rgba(33, 15, 6, 0.94), rgba(6, 3, 2, 0.96));
  box-shadow:
    0 0 0 2px rgba(14, 7, 3, 0.92),
    0 18px 42px rgba(0, 0, 0, 0.58),
    inset 0 0 36px rgba(255, 210, 112, 0.12);
  overflow: hidden;
  animation: turnPhaseBannerIn 1.35s ease both;
}

.turn-phase-banner::before,
.turn-phase-banner::after {
  content: "";
  position: absolute;
  left: 8%;
  right: 8%;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(255, 231, 161, 0.76), transparent);
}

.turn-phase-banner::before {
  top: 12px;
}

.turn-phase-banner::after {
  bottom: 12px;
}

.turn-phase-label {
  color: rgba(255, 231, 161, 0.76);
  font-size: 11px;
  font-weight: 950;
  letter-spacing: 1.8px;
}

.turn-phase-title {
  font-size: clamp(32px, 9vw, 48px);
  font-weight: 950;
  line-height: 1;
  color: #fff0b4;
  text-shadow:
    0 0 18px rgba(255, 217, 122, 0.42),
    0 3px 0 rgba(0, 0, 0, 0.72);
}

.turn-phase-subtitle {
  color: rgba(255, 236, 190, 0.88);
  font-size: 13px;
  font-weight: 850;
}

.turn-phase-ally {
