    linear-gradient(180deg, rgba(54, 8, 6, 0.95), rgba(13, 2, 2, 0.97));
}

.turn-phase-enemy .turn-phase-title {
  color: #ffd0c8;
  text-shadow:
    0 0 18px rgba(255, 84, 62, 0.52),
    0 3px 0 rgba(0, 0, 0, 0.74);
}

@keyframes turnPhaseBannerIn {
  0% {
    opacity: 0;
    transform: translate(-50%, -50%) scale(0.86);
    filter: blur(4px);
  }

  16% {
    opacity: 1;
