@keyframes dkV199102CutinBreath {
  0% { opacity: 0; filter: blur(2px) grayscale(0.28) brightness(0.8); }
  22% { opacity: 0.18; filter: blur(0) grayscale(0.18) brightness(0.95); }
  58% { opacity: 0.26; filter: blur(0) grayscale(0.08) brightness(1.08); }
  100% { opacity: 0.12; filter: blur(1px) grayscale(0.18) brightness(0.9); }
}

@keyframes dkV199102MeleeRoot {
  0%, 15% { transform: translateX(-28px); filter: brightness(1); }
  28% { transform: translateX(-50px) translateY(4px); filter: brightness(0.9); }
  42% { transform: translateX(32px) translateY(-6px); filter: brightness(1.28); }
  54%, 62% { transform: translateX(96px) translateY(-8px); filter: brightness(1.48); }
  76% { transform: translateX(24px); filter: brightness(1.08); }
  92%, 100% { transform: translateX(0); filter: brightness(1); }
}

@keyframes dkV199102MeleeRig {
  0%, 16% { transform: rotate(0deg) scale(1); }
  29% { transform: translate(-8px, 12px) rotate(-10deg) scaleX(0.96) scaleY(1.05); }
  43% { transform: translate(8px, -14px) rotate(11deg) scaleX(1.08) scaleY(0.94); }
  55%, 62% { transform: translate(18px, -5px) rotate(-16deg) scaleX(1.14) scaleY(0.88); }
  76% { transform: translate(0, 5px) rotate(6deg) scale(1); }
  92%, 100% { transform: rotate(0deg) scale(1); }
}

@keyframes dkV199102MeleeBody {
  0%, 18%, 100% { transform: rotate(0deg) scale(1); filter: brightness(1) saturate(1); }
  30% { transform: translateY(5px) rotate(-4deg) scaleX(0.98) scaleY(1.04); filter: brightness(0.95); }
  44% { transform: translateY(-11px) rotate(8deg) scaleX(1.08) scaleY(0.94); filter: brightness(1.28) saturate(1.10); }
  56%, 63% { transform: translateY(-4px) rotate(-15deg) scaleX(1.12) scaleY(0.88); filter: brightness(1.55) saturate(1.18); }
  78% { transform: translateY(2px) rotate(4deg) scale(1); filter: brightness(1.06); }
}

@keyframes dkV199102DefenderRoot {
  0%, 51% { transform: translateX(0); filter: brightness(1); }
  58%, 66% { transform: translateX(32px) translateY(-4px); filter: brightness(1.28); }
  78% { transform: translateX(-11px); filter: brightness(1.02); }
  92%, 100% { transform: translateX(0); filter: brightness(1); }
}

@keyframes dkV199102DefenderRig {
  0%, 51% { transform: rotate(0deg) scale(1); }
  58%, 66% { transform: translate(14px, -14px) rotate(-12deg) scaleX(1.10) scaleY(0.88); }
  78% { transform: translate(-6px, 4px) rotate(5deg) scaleX(0.98) scaleY(1.03); }
  92%, 100% { transform: rotate(0deg) scale(1); }
}

@keyframes dkV199102DefenderBody {
  0%, 51%, 100% { transform: scaleX(-1) translateY(0); filter: brightness(1) saturate(1); }
  58%, 66% { transform: scaleX(-1) translateY(-4px); filter: brightness(1.78) saturate(1.22); }
  78% { transform: scaleX(-1) translateY(3px); filter: brightness(0.98) saturate(0.96); }
}

@keyframes dkV199102CasterRoot {
  0%, 100% { transform: translateX(0); filter: brightness(1); }
  34% { transform: translateX(-10px) translateY(3px); filter: brightness(0.98); }
  50%, 64% { transform: translateX(14px) translateY(-10px); filter: brightness(1.26); }
  80% { transform: translateX(0); }
}

@keyframes dkV199102CasterRig {
  0%, 24%, 100% { transform: translateY(0) rotate(0deg) scale(1); }
  38% { transform: translateY(7px) rotate(-4deg) scaleX(0.98) scaleY(1.03); }
  52%, 64% { transform: translateY(-16px) rotate(-8deg) scale(1.05); }
  80% { transform: translateY(2px) rotate(2deg) scale(1); }
}

@keyframes dkV199102CasterBody {
  0%, 24%, 100% { transform: rotate(0deg) translate(0, 0) scale(1); filter: brightness(1) saturate(1); }
  38% { transform: rotate(-3deg) translate(0, 5px) scaleX(0.99) scaleY(1.02); }
  52%, 64% { transform: rotate(-9deg) translate(0, -10px) scale(1.05); filter: brightness(1.38) saturate(1.14); }
  80% { transform: rotate(2deg) translate(1px, 1px) scale(1); filter: brightness(1.03); }
}

@keyframes dkV199102ContactSlash {
  0%, 50% { opacity: 0; transform: translate(-110px, 22px) rotate(-25deg) scaleX(0.10); }
  55%, 62% { opacity: 1; transform: translate(-50%, -50%) rotate(-8deg) scaleX(1.08); }
  76%, 100% { opacity: 0; transform: translate(94px, -26px) rotate(7deg) scaleX(0.34); }
}

